pub enum InputError { InvalidInput }
pub fn dot(x: &[f64], w: &[f64]) -> Result<f64, InputError> {
    if x.is_empty() || x.len() > 64 || x.len() != w.len() || x.iter().chain(w).any(|v| !v.is_finite() || v.abs()>10000.0) { return Err(InputError::InvalidInput); }
    Ok(x.iter().zip(w).map(|(a,b)| a*b).sum())
}
','3+8=11. (1+2)(3+4)=21 — другая операция с лишними перекрёстными членами.');
