pub enum InputError { InvalidInput }
pub fn affine(x: &[f64], w: &[f64], b: f64) -> Result<f64, InputError> {
    if x.is_empty() || x.len() > 64 || x.len() != w.len() || !b.is_finite() || b.abs()>10000.0 || x.iter().chain(w).any(|v| !v.is_finite() || v.abs()>10000.0) { return Err(InputError::InvalidInput); }
    Ok(x.iter().zip(w).map(|(a,c)| a*c).sum::<f64>() + b)
}
