insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('81c7b884-4ec6-4fa7-82c4-c6cb19b1991c','ba9e9e01-6659-4782-8edb-fc50b92940d7','1cc72222ff3b3317037f69a0b26bd104e520b71810fda4c61ca0b237a50a87be','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"relu_and_grad"}'::jsonb,array['Значение и производная — разные величины.','Ветвь z>0, а не z≥0.']::text[],'import math

def relu_and_grad(z: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not _finite(z) or abs(z) > 10000:
        raise ValueError("Конечный z в ±10000")
    return [max(0.0, z), 1.0 if z > 0 else 0.0]
','При z=3 ответ [3,1], при z=−2 — [0,0], при z=0 — [0,0] по выбранной convention.');
