insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('372f2176-2dc5-440a-880d-8c56db4811bc','df053995-1f69-4247-8f6d-774753dd7ce0','ba9e9e01-6659-4782-8edb-fc50b92940d7','372f2176-2dc5-440a-880d-8c56db4811bc','unit.neuron.dense.guided',0,'Сохранить оси batch и output','Напишите dense_batch(X,W,b), где X имеет B×I, W — O×I, b — O; результат B×O. Оси B,I,O от 1 до 64, все строки одинаковой ширины I. Векторы — непустые, длина 1–64, формы совпадают, числа конечны в ±10000; исходные данные не менять. Невалидный вход: ValueError/RangeError/InputError (Python wrong types может дать TypeError). Сравнение atol=1e−12, rtol=1e−10.

Yⱼₖ=ΣᵢXⱼᵢWₖᵢ+bₖ');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('1cd189c7-367a-42b1-8dcf-5726cc70d574','372f2176-2dc5-440a-880d-8c56db4811bc','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def dense_batch(x: list[list[float]], w: list[list[float]], b: list[float]) -> list[list[float]]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    raise NotImplementedError("Реализуйте формулу и контракт")
','dense_batch','[{"input":{"x":[[1,2],[-1,0]],"w":[[2,3],[-1,4],[0,2]],"b":[1,-2,3]},"output":[[9,5,7],[-1,-1,3]]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('1cd189c7-367a-42b1-8dcf-5726cc70d574','ba9e9e01-6659-4782-8edb-fc50b92940d7','a4cd8bdcd63fad94ceb58a273777866b918fc9a97d2e4f9983ba439abb73e785','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"dense_batch"}'::jsonb,array['Для каждой строки X вычислите dot с каждой строкой W.','Bias выбирается по output k, не по batch j.']::text[],'import math

def dense_batch(x: list[list[float]], w: list[list[float]], b: list[float]) -> list[list[float]]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not x or not w or not x[0] or max(len(x), len(w), len(x[0])) > 64 or len(w) != len(b):
        raise ValueError("Оси B,I,O должны быть 1–64")
    width = len(x[0])
    if any(len(row) != width for row in x + w) or any(not _finite(v) or abs(v)>10000 for row in x + w + [b] for v in row):
        raise ValueError("Несовместимые строки")
    return [[sum(a*c for a,c in zip(row, weights)) + bias for weights,bias in zip(w,b)] for row in x]
','При X=[[1,2],[−1,0]], W=[[2,3],[−1,4],[0,2]], b=[1,−2,3] выход [[9,5,7],[−1,−1,3]].');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('8fc124e4-e604-4699-851a-a60663da5ee6','372f2176-2dc5-440a-880d-8c56db4811bc','ba9e9e01-6659-4782-8edb-fc50b92940d7','javascript','function denseBatch(x, w, b) {
  throw new Error("Реализуйте формулу и контракт");
}
','denseBatch','[{"input":{"x":[[1,2],[-1,0]],"w":[[2,3],[-1,4],[0,2]],"b":[1,-2,3]},"output":[[9,5,7],[-1,-1,3]]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('8fc124e4-e604-4699-851a-a60663da5ee6','ba9e9e01-6659-4782-8edb-fc50b92940d7','0985f4b8fb58f6f2311f01a1a16dbb477f0d90f98b3ccaeb014708fd696043e1','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"denseBatch"}'::jsonb,array['Для каждой строки X вычислите dot с каждой строкой W.','Bias выбирается по output k, не по batch j.']::text[],'function denseBatch(x, w, b) {
  if (!Array.isArray(x) || !Array.isArray(w) || !Array.isArray(b) || !x.length || !w.length || !Array.isArray(x[0]) || !x[0].length || Math.max(x.length,w.length,x[0].length)>64 || w.length!==b.length) throw new RangeError("Некорректные оси");
  const width=x[0].length;
  if ([...x,...w].some(row=>!Array.isArray(row)||row.length!==width) || [...x.flat(),...w.flat(),...b].some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>10000)) throw new RangeError("Некорректные строки");
  return x.map(row=>w.map((weights,j)=>row.reduce((sum,v,i)=>sum+v*weights[i],b[j])));
}
','При X=[[1,2],[−1,0]], W=[[2,3],[−1,4],[0,2]], b=[1,−2,3] выход [[9,5,7],[−1,−1,3]].');
