pub enum InputError { InvalidInput }
pub fn dense_batch(x: &[Vec<f64>], w: &[Vec<f64>], b: &[f64]) -> Result<Vec<Vec<f64>>, InputError> {
    if x.is_empty() || w.is_empty() || x[0].is_empty() || x.len()>64 || w.len()>64 || x[0].len()>64 || w.len()!=b.len() { return Err(InputError::InvalidInput); }
    let width=x[0].len();
    if x.iter().chain(w).any(|row|row.len()!=width) || x.iter().chain(w).flatten().chain(b).any(|v|!v.is_finite()||v.abs()>10000.0) { return Err(InputError::InvalidInput); }
    Ok(x.iter().map(|row|w.iter().zip(b).map(|(weights,bias)|row.iter().zip(weights).map(|(a,c)|a*c).sum::<f64>()+bias).collect()).collect())
}
','При X=[[1,2],[−1,0]], W=[[2,3],[−1,4],[0,2]], b=[1,−2,3] выход [[9,5,7],[−1,−1,3]].');
