insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('c3b335fa-310e-4160-8a2b-c71fa79f2b3e','ba9e9e01-6659-4782-8edb-fc50b92940d7','8763f313ad72bcde1ae737de761a8d95670189b5a0c4003c525da72f13ab7fd5','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"mse_loss"}'::jsonb,array['Сначала найдите разности [1,2] для p=[1,3],t=[0,1].','Mean и sum отличаются в n раз.']::text[],'import math

def mse_loss(predictions: list[float], targets: list[float]) -> float:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1 <= len(predictions) <= 64 or len(predictions) != len(targets) or any(not _finite(v) or abs(v)>10000 for v in predictions+targets):
        raise ValueError("Непустые согласованные predictions/targets")
    return sum((p-t)**2 for p,t in zip(predictions,targets))/len(predictions)
','Квадраты [1,4], MSE=2.5. Знак ошибки исчезает при возведении в квадрат, но не при вычислении gradient.');
