  if (!Array.isArray(predictions)||!Array.isArray(targets)||!predictions.length||predictions.length>64||predictions.length!==targets.length||[...predictions,...targets].some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>10000)) throw new RangeError("Некорректные predictions/targets");
  return predictions.reduce((sum,p,i)=>sum+(p-targets[i])**2,0)/predictions.length;
}
