insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('da74f804-ae0a-4f90-8f7b-9114fd52130c','ba9e9e01-6659-4782-8edb-fc50b92940d7','a9179ec78933acef9c32077938dfb4f8b67f4b9cd990df0c76223a36acc254c3','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"mse_loss"}'::jsonb,array['И числитель, и длина увеличиваются вдвое.']::text[],'import math

def mse_loss(predictions: list[float], targets: list[float]) -> float:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1 <= len(predictions) <= 64 or len(predictions) != len(targets) or any(not _finite(v) or abs(v)>10000 for v in predictions+targets):
        raise ValueError("Непустые согласованные predictions/targets")
    return sum((p-t)**2 for p,t in zip(predictions,targets))/len(predictions)
