insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('1e08cd21-a988-4215-8b65-5ad500983320','c03977ce-8f66-4749-8720-770e2c8a615e','ba9e9e01-6659-4782-8edb-fc50b92940d7','1e08cd21-a988-4215-8b65-5ad500983320','unit.loss.bce.guided',0,'Устойчивая loss без log(0)','Реализуйте bce_logit(z,y). z конечен в ±10000, label y строго 0 или 1. Используйте log1p и exp(−abs(z)); не вычисляйте sigmoid и затем log округлённой вероятности. Невалидные данные отклоняются.

BCE(z,y)=max(z,0)−zy+log(1+exp(−|z|))');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('110f750f-8e2f-4bd0-82d3-e22eaf6c9180','1e08cd21-a988-4215-8b65-5ad500983320','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def bce_logit(z: float, y: float) -> float:
