','bce_logit','[{"input":{"z":0,"y":0},"output":0.6931471805599453},{"input":{"z":0,"y":1},"output":0.6931471805599453},{"input":{"z":1000,"y":0},"output":1000},{"input":{"z":1000,"y":1},"output":0}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('110f750f-8e2f-4bd0-82d3-e22eaf6c9180','ba9e9e01-6659-4782-8edb-fc50b92940d7','fb08333f0822122449436161f257e9b05fb71e3142c14aa9a1e007d30b57ff1a','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"bce_logit"}'::jsonb,array['В exp попадает неположительный аргумент.','log1p(x) точнее log(1+x), когда x мал.']::text[],'import math

def bce_logit(z: float, y: float) -> float:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not _finite(z) or abs(z)>10000 or (type(y) not in (int,float) or y not in (0,1)):
        raise ValueError("Конечный z в ±10000 и y∈{0,1}")
    return max(z,0.0)-z*y+math.log1p(math.exp(-abs(z)))
','При z=0 оба labels дают ln2. При z=1000,y=0 loss≈1000, при y=1≈0, без Infinity/NaN.');
