insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('e3792ed2-b2a1-4c35-8239-8ba5eeee0535','ba9e9e01-6659-4782-8edb-fc50b92940d7','20bbf29f84dc558009f466bfbc964610c2465ad8771dd3fff876b960fde04f35','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"bceLogit"}'::jsonb,array['В exp попадает неположительный аргумент.','log1p(x) точнее log(1+x), когда x мал.']::text[],'function bceLogit(z, y) {
  if (typeof z!=="number"||!Number.isFinite(z)||Math.abs(z)>10000||(y!==0&&y!==1)) throw new RangeError("Некорректный logit/label");
  return Math.max(z,0)-z*y+Math.log1p(Math.exp(-Math.abs(z)));
}
','При z=0 оба labels дают ln2. При z=1000,y=0 loss≈1000, при y=1≈0, без Infinity/NaN.');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('2696afe3-4693-446d-831c-8f7e76232988','1e08cd21-a988-4215-8b65-5ad500983320','ba9e9e01-6659-4782-8edb-fc50b92940d7','rust','#[derive(Debug, PartialEq)]
