}
','bce_logit','[{"input":{"z":0,"y":0},"output":0.6931471805599453},{"input":{"z":0,"y":1},"output":0.6931471805599453},{"input":{"z":1000,"y":0},"output":1000},{"input":{"z":1000,"y":1},"output":0}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('2696afe3-4693-446d-831c-8f7e76232988','ba9e9e01-6659-4782-8edb-fc50b92940d7','6b4a2c373ab193a6c82561e2daacf04af27cb5dd8862a890c853a86c250f8c3b','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"bce_logit"}'::jsonb,array['В exp попадает неположительный аргумент.','log1p(x) точнее log(1+x), когда x мал.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn bce_logit(z: f64, y: f64) -> Result<f64, InputError> {
    if !z.is_finite() || z.abs()>10000.0 || (y!=0.0 && y!=1.0) { return Err(InputError::InvalidInput); }
    Ok(z.max(0.0)-z*y+(-z.abs()).exp().ln_1p())
}
','При z=0 оба labels дают ln2. При z=1000,y=0 loss≈1000, при y=1≈0, без Infinity/NaN.');
