','activation_and_grad','[{"input":{"z":0,"kind":"sigmoid"},"output":[0.5,0.25]},{"input":{"z":0,"kind":"tanh"},"output":[0,1]},{"input":{"z":0,"kind":"relu"},"output":[0,0]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('d714dbaa-ba4e-401e-8300-5278c2bb430f','ba9e9e01-6659-4782-8edb-fc50b92940d7','dec1cad1fe429c73658c1247f39a8dd4e4c3357df3358521b81cdf8bf5a941ef','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"activation_and_grad"}'::jsonb,array['Обратите внимание на разные derivatives в одной и той же точке 0.']::text[],'import math

def activation_and_grad(z: float, kind: str) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not _finite(z) or abs(z)>10000 or kind not in ("relu","sigmoid","tanh"):
        raise ValueError("Некорректная activation")
    if kind=="relu":
        return [max(0.0,z),1.0 if z>0 else 0.0]
    if kind=="tanh":
        a=math.tanh(z)
        return [a,1-a*a]
    e=math.exp(-abs(z))
    a=1/(1+e) if z>=0 else e/(1+e)
    return [a,a*(1-a)]
','При z=0 sigmoid=.5, derivative=.25; tanh=0, derivative=1; ReLU value=0, convention derivative=0.');
