    if !z.is_finite()||z.abs()>10000.0{return Err(InputError::InvalidInput);}
    let (a,g)=match kind{"relu"=>(z.max(0.0),if z>0.0{1.0}else{0.0}),"tanh"=>{let a=z.tanh();(a,1.0-a*a)},"sigmoid"=>{let e=(-z.abs()).exp();let a=if z>=0.0{1.0/(1.0+e)}else{e/(1.0+e)};(a,a*(1.0-a))},_=>return Err(InputError::InvalidInput)};
