insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('b34d532d-02b6-4972-86c3-08bf56013e09','ba9e9e01-6659-4782-8edb-fc50b92940d7','36f25421b188ce882f3e5a6a663fbaf43c18e63e65bd025389c10753abfbcc3e','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"shared_graph_backward"}'::jsonb,array['Производная квадрата берётся в q, а не в x.','Прямая ветвь q добавляет 1. При q=−0.5 вклады −1 и +1 взаимно уничтожаются.']::text[],'import math

def shared_graph_backward(x: float, w: float, b: float) -> dict[str, float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if any(not _finite(v) or abs(v) > 4 for v in (x, w, b)):
        raise ValueError("Конечные x,w,b в пределах ±4")
    q = w * x + b
    loss = q * q + 1 * q
    dq = 2 * q + 1
    return {"q": q, "loss": loss, "dx": dq * w, "dw": dq * x, "db": dq}
','Для x=2,w=3,b=1: q=7,L=56,dq=15,dx=45,dw=30,db=15. Каждый путь даёт вклад; перезапись dq вместо сложения теряет ветвь.');
