pub enum InputError { InvalidInput }
#[derive(Debug)]
pub struct GraphResult { pub q: f64, pub loss: f64, pub dx: f64, pub dw: f64, pub db: f64 }
pub fn shared_graph_backward(x: f64, w: f64, b: f64) -> Result<GraphResult, InputError> {
    if [x, w, b].iter().any(|v| !v.is_finite() || v.abs() > 4.0) { return Err(InputError::InvalidInput); }
    let q = w * x + b;
    let loss = q * q + 1.0 * q;
    let dq = 2.0 * q + 1.0;
    Ok(GraphResult { q, loss, dx: dq * w, dw: dq * x, db: dq })
}
