insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('889440cc-f37d-471b-8365-7b66f6150f99','37f723c4-2f3a-4ec2-8d64-f3a04f77d0fa','ba9e9e01-6659-4782-8edb-fc50b92940d7','889440cc-f37d-471b-8365-7b66f6150f99','unit.backprop.check.guided',0,'Центральная разность по одной координате','Напишите central_gradient(x,w,b,h) для L=(wx+b)²+(wx+b). Верните [dx,dw,db]. Меняйте одну координату на ±h, остальные фиксируйте. x,w,b конечны в ±4, h∈[1e−6,1e−4]. Не вызывайте аналитический backward. Сравнение finite difference atol=1e−7,rtol=1e−6.

∂L/∂θᵢ≈[L(θ+h·eᵢ)−L(θ−h·eᵢ)]/(2h)');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('50a4177b-36ce-46b2-8d0a-868c62ad536a','889440cc-f37d-471b-8365-7b66f6150f99','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def central_gradient(x: float, w: float, b: float, h: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    raise NotImplementedError("Реализуйте формулу и контракт")
','central_gradient','[{"input":{"x":2,"w":3,"b":1,"h":0.00001},"output":[45,30,15]},{"input":{"x":1,"w":-1,"b":0.5,"h":0.00001},"output":[0,0,0]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('50a4177b-36ce-46b2-8d0a-868c62ad536a','ba9e9e01-6659-4782-8edb-fc50b92940d7','1c5e2d2e3b42aeb6756d0a050c3981261f10c1b41e35835745ba2762c90980c2','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"central_gradient"}'::jsonb,array['Копируйте точку отдельно для plus и minus.','Знаменатель 2h, не h.']::text[],'import math

def central_gradient(x: float, w: float, b: float, h: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if any(not _finite(v) or abs(v)>4 for v in (x,w,b)) or not _finite(h) or not 1e-6<=h<=1e-4:
        raise ValueError("x,w,b в ±4 и h∈[1e−6,1e−4]")
    def loss(a,c,d):
        q=c*a+d
        return q*q+q
    point=[x,w,b]
    result=[]
    for i in range(3):
        plus=point.copy(); minus=point.copy()
        plus[i]+=h; minus[i]-=h
        result.append((loss(*plus)-loss(*minus))/(2*h))
    return result
','При [x,w,b]=[2,3,1] центральная разность должна приблизиться к [45,30,15]. Для гладкого полинома это независимая проверка, а не повторение формулы backward.');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('b03c961f-b5c1-493e-807c-294ef4fc56d7','889440cc-f37d-471b-8365-7b66f6150f99','ba9e9e01-6659-4782-8edb-fc50b92940d7','javascript','function centralGradient(x, w, b, h) {
  throw new Error("Реализуйте формулу и контракт");
}
','centralGradient','[{"input":{"x":2,"w":3,"b":1,"h":0.00001},"output":[45,30,15]},{"input":{"x":1,"w":-1,"b":0.5,"h":0.00001},"output":[0,0,0]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('b03c961f-b5c1-493e-807c-294ef4fc56d7','ba9e9e01-6659-4782-8edb-fc50b92940d7','da97268392664532edb5350ee0ae3b0bdfc62e4b893b7c1f8ce01cce7043421d','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"centralGradient"}'::jsonb,array['Копируйте точку отдельно для plus и minus.','Знаменатель 2h, не h.']::text[],'function centralGradient(x, w, b, h) {
  if ([x,w,b].some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>4)||typeof h!=="number"||!Number.isFinite(h)||h<1e-6||h>1e-4) throw new RangeError("Некорректная точка/h");
  const loss=(a,c,d)=>{const q=c*a+d;return q*q+q;};
  const point=[x,w,b];
  return point.map((_,i)=>{const plus=[...point],minus=[...point];plus[i]+=h;minus[i]-=h;return (loss(...plus)-loss(...minus))/(2*h);});
}
','При [x,w,b]=[2,3,1] центральная разность должна приблизиться к [45,30,15]. Для гладкого полинома это независимая проверка, а не повторение формулы backward.');
