insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('9de0bfa9-6192-4baf-8f06-7cce68c8a630','ba9e9e01-6659-4782-8edb-fc50b92940d7','010f09bacfefe3aef62fbc605168c3408f4baa67614fefa6433f4ddde835990c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"central_gradient"}'::jsonb,array['Копируйте точку отдельно для plus и minus.','Знаменатель 2h, не h.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn central_gradient(x: f64, w: f64, b: f64, h: f64) -> Result<Vec<f64>, InputError> {
    if [x,w,b].iter().any(|v|!v.is_finite()||v.abs()>4.0) || !h.is_finite() || !(1e-6..=1e-4).contains(&h) { return Err(InputError::InvalidInput); }
    let loss=|p: [f64;3]|{let q=p[1]*p[0]+p[2];q*q+q};
    let point=[x,w,b];
    Ok((0..3).map(|i|{let mut plus=point;let mut minus=point;plus[i]+=h;minus[i]-=h;(loss(plus)-loss(minus))/(2.0*h)}).collect())
}
','При [x,w,b]=[2,3,1] центральная разность должна приблизиться к [45,30,15]. Для гладкого полинома это независимая проверка, а не повторение формулы backward.');
