insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('5d196752-830d-4ac4-868b-875dc4d6859d','ba9e9e01-6659-4782-8edb-fc50b92940d7','fe91a299988844b6f52fb7c09d86b0e4c72e83455c87e985ee8348063299733b','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"central_gradient"}'::jsonb,array['Оба h должны дать согласованные gradients в допуске.']::text[],'import math

def central_gradient(x: float, w: float, b: float, h: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if any(not _finite(v) or abs(v)>4 for v in (x,w,b)) or not _finite(h) or not 1e-6<=h<=1e-4:
        raise ValueError("x,w,b в ±4 и h∈[1e−6,1e−4]")
    def loss(a,c,d):
        q=c*a+d
        return q*q+q
    point=[x,w,b]
    result=[]
    for i in range(3):
        plus=point.copy(); minus=point.copy()
        plus[i]+=h; minus[i]-=h
        result.append((loss(*plus)-loss(*minus))/(2*h))
    return result
','По w gradient положительный, по x и b — отрицательный. Слишком малый h вообще может усилить roundoff; h не означает универсальную точность.');
