insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('620c742c-3acc-493e-8bff-9a6d262e93ba','ba9e9e01-6659-4782-8edb-fc50b92940d7','100713f3e74488e3f087483f69b43273566df9775c8bfc1c269037a41efaaa53','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"sgd_step"}'::jsonb,array['Положительная производная означает рост loss при росте параметра; шаг должен уменьшить параметр.','При eta=0 верните новый массив с прежними значениями.']::text[],'import math

def sgd_step(theta: list[float], grad: list[float], eta: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not theta or len(theta) != len(grad) or not _finite(eta) or not 0 <= eta <= 1 or any(not _finite(v) or abs(v) > 10000 for v in theta + grad):
        raise ValueError("Формы, конечные параметры и eta в [0,1]")
    return [t - eta * g for t, g in zip(theta, grad)]
','delta=[−0.2,−0.8], theta_new=[1.8,0.2]. На L=(x²+8y²)/2 это меняет loss с 6 до 1.78. Сам SGD не знает эту loss и не гарантирует снижение при любом eta.');
