    if [theta,m,grad].iter().any(|a|!a.is_finite()||a.abs()>10000.0)||!v.is_finite()||!(0.0..=1e8).contains(&v)||!eta.is_finite()||!(0.0..=1.0).contains(&eta)||[beta1,beta2].iter().any(|a|!a.is_finite()||!(0.0..1.0).contains(a))||t==0||t>1000000||!eps.is_finite()||!(1e-12..=1.0).contains(&eps){return Err(InputError::InvalidInput);}
    let m_new=beta1*m+(1.0-beta1)*grad;
    let v_new=beta2*v+(1.0-beta2)*grad*grad;
    let m_hat=m_new/(1.0-beta1.powi(t as i32));
    let v_hat=v_new/(1.0-beta2.powi(t as i32));
    Ok(vec![theta-eta*m_hat/(v_hat.sqrt()+eps),m_new,v_new])
}
','Новые theta: 1−.2/2.1 и 1−2/20.1. Без epsilon величины были бы равны для положительных g; с epsilon отличаются.');
