def standardize(train: list[float], heldout: list[float]) -> dict[str, object]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1<=len(train)<=64 or len(heldout)>64 or any(not _finite(a) or abs(a)>10000 for a in train+heldout):
        raise ValueError("Неверные данные")
    mean=sum(train)/len(train)
    variance=sum((a-mean)**2 for a in train)/len(train)
    scale=math.sqrt(variance) if variance>0 else 1.0
    return {"mean":mean,"scale":scale,"values":[(a-mean)/scale for a in heldout]}
','Train [1,3] задаёт μ=2,s=1; held-out [2,4] → [0,2].');
