pub enum InputError { InvalidInput }
pub struct Standardized { pub mean:f64, pub scale:f64, pub values:Vec<f64> }
pub fn standardize(train: &[f64], heldout: &[f64]) -> Result<Standardized, InputError> {
    if train.is_empty()||train.len()>64||heldout.len()>64||train.iter().chain(heldout).any(|a|!a.is_finite()||a.abs()>10000.0){return Err(InputError::InvalidInput);}
    let mean=train.iter().sum::<f64>()/train.len() as f64;
    let variance=train.iter().map(|a|(a-mean).powi(2)).sum::<f64>()/train.len() as f64;
    let scale=if variance>0.0{variance.sqrt()}else{1.0};
    Ok(Standardized{mean,scale,values:heldout.iter().map(|a|(a-mean)/scale).collect()})
}
','Train [1,3] задаёт μ=2,s=1; held-out [2,4] → [0,2].');
