def group_membership(groups: list[int], train_groups: list[int]) -> list[int]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if len(groups)>64 or len(train_groups)>64 or any(not type(g) is int or g<0 or g>1000000 for g in groups+train_groups):
        raise ValueError("Неверные group IDs")
    selected=set(train_groups)
    return [1 if g in selected else 0 for g in groups]
