def train_batch(theta: list[float], x: list[float], y: list[float], eta: float, l2: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if len(theta)!=2 or not 1<=len(x)<=64 or len(x)!=len(y) or any(not _finite(a) or abs(a)>100 for a in theta+x) or any((type(a) not in (int,float) or a not in (0,1)) for a in y) or not _finite(eta) or not 0<=eta<=1 or not _finite(l2) or not 0<=l2<=1:
        raise ValueError("Неверный batch/state")
    gw=gb=0.0
    for a,label in zip(x,y):
        z=theta[0]*a+theta[1]
        e=math.exp(-abs(z)); p=1/(1+e) if z>=0 else e/(1+e)
        gw+=(p-label)*a/len(x); gb+=(p-label)/len(x)
    gw+=l2*theta[0]
    return [theta[0]-eta*gw,theta[1]-eta*gb]
','При theta=0,batch x=[−1,1],y=[0,1] gradient w=−.5,b=0; eta=.2 даёт [.1,0].');
