insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('1d178616-3549-429a-8cf3-48394569a45d','ba9e9e01-6659-4782-8edb-fc50b92940d7','2d3a9da4da51aba64945860fdfaf81d0692c878a6a4f370791fd4c2ed59f0a28','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"train_batch"}'::jsonb,array['Не обновляйте params внутри цикла отдельных samples.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn train_batch(theta: &[f64], x: &[f64], y: &[f64], eta: f64, l2: f64) -> Result<Vec<f64>, InputError> {
    if theta.len()!=2||x.is_empty()||x.len()>64||x.len()!=y.len()||theta.iter().chain(x).any(|a|!a.is_finite()||a.abs()>100.0)||y.iter().any(|a|*a!=0.0&&*a!=1.0)||!eta.is_finite()||!(0.0..=1.0).contains(&eta)||!l2.is_finite()||!(0.0..=1.0).contains(&l2){return Err(InputError::InvalidInput);}
    let(mut gw,mut gb)=(0.0,0.0);
    for(a,label)in x.iter().zip(y){let z=theta[0]*a+theta[1];let e=(-z.abs()).exp();let p=if z>=0.0{1.0/(1.0+e)}else{e/(1.0+e)};gw+=(p-label)*a/x.len() as f64;gb+=(p-label)/x.len() as f64;}
    gw+=l2*theta[0];
    Ok(vec![theta[0]-eta*gw,theta[1]-eta*gb])
}
','При theta=0,batch x=[−1,1],y=[0,1] gradient w=−.5,b=0; eta=.2 даёт [.1,0].');
