insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('3031fcca-9aad-4f76-8e4a-9f42bd94058a','ba9e9e01-6659-4782-8edb-fc50b92940d7','58c6a110e3803a5715e4b6754f615e8e6ce774ff2edca48776fca387dd508671','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"train_batch"}'::jsonb,array['Посчитайте data и penalty вклады отдельно.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn train_batch(theta: &[f64], x: &[f64], y: &[f64], eta: f64, l2: f64) -> Result<Vec<f64>, InputError> {
    if theta.len()!=2||x.is_empty()||x.len()>64||x.len()!=y.len()||theta.iter().chain(x).any(|a|!a.is_finite()||a.abs()>100.0)||y.iter().any(|a|*a!=0.0&&*a!=1.0)||!eta.is_finite()||!(0.0..=1.0).contains(&eta)||!l2.is_finite()||!(0.0..=1.0).contains(&l2){return Err(InputError::InvalidInput);}
    let(mut gw,mut gb)=(0.0,0.0);
    for(a,label)in x.iter().zip(y){let z=theta[0]*a+theta[1];let e=(-z.abs()).exp();let p=if z>=0.0{1.0/(1.0+e)}else{e/(1.0+e)};gw+=(p-label)*a/x.len() as f64;gb+=(p-label)/x.len() as f64;}
    gw+=l2*theta[0];
    Ok(vec![theta[0]-eta*gw,theta[1]-eta*gb])
}
','Новые theta [1.85,−2.05]. Regularizing bias было бы иной loss convention.');
