pub fn hidden_features(points: &[Vec<f64>], weights: &[f64], bias: f64) -> Result<Vec<f64>, InputError> {
    if points.is_empty()||points.len()>64||weights.is_empty()||weights.len()>64||points.iter().any(|p|p.len()!=weights.len())||points.iter().flatten().chain(weights).chain(std::iter::once(&bias)).any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}
    Ok(points.iter().map(|p|(p.iter().zip(weights).map(|(a,w)|a*w).sum::<f64>()+bias).tanh()).collect())
}
','Ответ [tanh1,−tanh1]. Output head мог бы компенсировать смену знака своим weight и сохранить predictions.');
