insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('ca498538-c8eb-4991-8d1e-cdf9a14306e9','ba9e9e01-6659-4782-8edb-fc50b92940d7','075157465790159f18db3cccbab2ffd55f4d9cb62c6ced45591a77bff4fb84cf','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"xor_example"}'::jsonb,array['Инициализация нужна для нарушения симметрии hidden units.']::text[],'import math

def xor_example(params: list[float], xy: list[float], target: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if len(params)!=17 or len(xy)!=2 or (type(target) not in (int,float) or target not in (0,1)) or any(not _finite(a) or abs(a)>10 for a in params+xy):
        raise ValueError("Нужны 17 params, 2 inputs, binary target")
    h=[math.tanh(params[2*j]*xy[0]+params[2*j+1]*xy[1]+params[8+j]) for j in range(4)]
    z=sum(params[12+j]*h[j] for j in range(4))+params[16]
    e=math.exp(-abs(z)); p=1/(1+e) if z>=0 else e/(1+e)
    loss=max(z,0)-z*target+math.log1p(e)
    dz=p-target
    g=[0.0]*17
    for j in range(4):
        dh=dz*params[12+j]*(1-h[j]*h[j])
        g[2*j]=dh*xy[0];g[2*j+1]=dh*xy[1];g[8+j]=dh;g[12+j]=dz*h[j]
    g[16]=dz
    return [loss]+g
','Полный XOR batch при нулевой инициализации даёт нулевой gradient всех17params; сеть не начнёт учиться от этого шага.');
