pub enum InputError { InvalidInput }
pub fn sgd_step(theta: &[f64], grad: &[f64], eta: f64) -> Result<Vec<f64>, InputError> {
    if theta.is_empty() || theta.len() != grad.len() || !eta.is_finite() || !(0.0..=1.0).contains(&eta) || theta.iter().chain(grad).any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    Ok(theta.iter().zip(grad).map(|(t, g)| t - eta * g).collect())
}
