insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('a92033df-3d46-4add-8645-09df6ddfae8e','ba9e9e01-6659-4782-8edb-fc50b92940d7','8aee11a681ab2beb486992a938d01c5e372b514e99a79d7b01d10c1f35e24bf6','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"confusion_matrix"}'::jsonb,array['Сначала predicted label, затем сопоставление true label.']::text[],'import math

def confusion_matrix(p: list[float], y: list[float], threshold: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1<=len(p)<=64 or len(p)!=len(y) or any(not _finite(a) or not 0<=a<=1 for a in p+[threshold]) or any((type(a) not in (int,float) or a not in (0,1)) for a in y):
        raise ValueError("Неверные probabilities/labels")
    tp=fp=fn=tn=0
    for a,label in zip(p,y):
        positive=a>=threshold
        if positive and label==1: tp+=1
        elif positive: fp+=1
        elif label==1: fn+=1
        else: tn+=1
    return [tp,fp,fn,tn]
','Для p=[.9,.7,.4,.1],y=[1,0,1,0],threshold=.5: по одному TP,FP,FN,TN.');
