insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('e299aee3-4c16-4742-8d46-d19e08c3d1d4','ba9e9e01-6659-4782-8edb-fc50b92940d7','4497f0d9fc22f606ccfefea45c6af2d6efccdd319e0b2f5de355e682d8b62dc1','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"confusionMatrix"}'::jsonb,array['Сначала predicted label, затем сопоставление true label.']::text[],'function confusionMatrix(p, y, threshold) {
  if(!Array.isArray(p)||!Array.isArray(y)||!p.length||p.length>64||p.length!==y.length||[...p,threshold].some(a=>!Number.isFinite(a)||a<0||a>1)||y.some(a=>a!==0&&a!==1))throw new RangeError("Неверные probabilities/labels");
  const counts=[0,0,0,0];
  p.forEach((a,i)=>counts[a>=threshold?(y[i]===1?0:1):(y[i]===1?2:3)]++);
  return counts;
