    tp=fp=fn=tn=0
    for a,label in zip(p,y):
        positive=a>=threshold
        if positive and label==1: tp+=1
        elif positive: fp+=1
        elif label==1: fn+=1
        else: tn+=1
    return [tp,fp,fn,tn]
