insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('c4dda977-fda0-463f-8388-82d09155b3dc','ba9e9e01-6659-4782-8edb-fc50b92940d7','d5cf223061e861fdea96daae357096a0ceb0e391bb859fc98aa2dadd736b495c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"embedding_lookup"}'::jsonb,array['Lookup — выбор строки table.']::text[],'import math

def embedding_lookup(ids: list[int], table: list[list[float]], positions: list[list[float]]) -> list[list[float]]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1<=len(ids)<=64 or not 1<=len(table)<=64 or not table[0] or len(table[0])>64 or len(positions)!=len(ids) or any(not type(i) is int or i<0 or i>=len(table) for i in ids):
        raise ValueError("Неверные ids/table/positions")
    d=len(table[0])
    if any(len(row)!=d for row in table+positions) or any(not _finite(a) or abs(a)>10000 for row in table+positions for a in row):
        raise ValueError("Неверная ширина/значения")
    return [[a+b for a,b in zip(table[i],pos)] for i,pos in zip(ids,positions)]
','Для ids=[1,0], E=[[1,2],[3,4]], P=[[0,0],[1,−1]] результат [[3,4],[2,1]]. ID выбирает строку, не задаёт величину feature.');
