  if(!Array.isArray(ids)||!Array.isArray(table)||!Array.isArray(positions)||!ids.length||ids.length>64||!table.length||table.length>64||!Array.isArray(table[0])||!table[0].length||table[0].length>64||positions.length!==ids.length||ids.some(i=>!Number.isInteger(i)||i<0||i>=table.length))throw new RangeError("Неверные ids/table/positions");
  const d=table[0].length;if([...table,...positions].some(row=>!Array.isArray(row)||row.length!==d)||[...table.flat(),...positions.flat()].some(a=>!Number.isFinite(a)||Math.abs(a)>10000))throw new RangeError("Неверная ширина/значения");
  return ids.map((id,j)=>table[id].map((a,i)=>a+positions[j][i]));
}
