    let scores:Vec<f64>=keys.iter().map(|k|query.iter().zip(k).map(|(a,b)|a*b).sum::<f64>()/(query.len() as f64).sqrt()).collect();
    let m=scores.iter().zip(allowed).filter(|(_,ok)|**ok).map(|(s,_)|*s).fold(f64::NEG_INFINITY,f64::max);
    let e:Vec<f64>=scores.iter().zip(allowed).map(|(s,ok)|if *ok{(s-m).exp()}else{0.0}).collect();let total:f64=e.iter().sum();let weights:Vec<f64>=e.iter().map(|a|a/total).collect();
    let out=(0..values[0].len()).map(|i|values.iter().zip(&weights).map(|(v,a)|a*v[i]).sum()).collect();
    Ok(AttentionResult{weights,out})
}
','Output=.25·1+.75·5=4. Если забыть scale, weights будут .1/.9 и output 4.6: fixture различает ошибку.');
