insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('bfcfdc18-0375-4b1c-83b2-cfe1d08077d6','ba9e9e01-6659-4782-8edb-fc50b92940d7','efd06a6741ab35edb7765167dda4a329f73708589e305ed0360d3a6734abbd01','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"grouped_mix"}'::jsonb,array['Sharing values не означает sharing query weights.']::text[],'import math

def grouped_mix(weights: list[list[float]], values: list[list[float]]) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1<=len(values)<=len(weights)<=64 or len(weights)%len(values) or not values[0] or len(values[0])>64:
        raise ValueError("Неверное число heads/tokens")
    n=len(values[0])
    if any(len(row)!=n for row in weights+values) or any(not _finite(a) or abs(a)>100 for row in weights+values for a in row) or any(any(a<0 for a in row) or abs(sum(row)-1)>1e-10 for row in weights):
        raise ValueError("Неверные weights/values")
    group=len(weights)//len(values)
    return [sum(a*v for a,v in zip(row,values[h//group])) for h,row in enumerate(weights)]
','Weights [[1,0],[0,1],[.5,.5],[.25,.75]], shared values [[2,4],[10,20]] дают [2,4,15,17.5]. Q heads имеют разные weights при общей KV group.');
