insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('f2b36a90-7b54-47e9-8926-05f94231a000','ba9e9e01-6659-4782-8edb-fc50b92940d7','98a5840085eee7d81f11a82eb6c8dffa8c073899e0e4c427dba5aee58f3809cc','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"groupedMix"}'::jsonb,array['Sharing values не означает sharing query weights.']::text[],'function groupedMix(weights, values) {
  if(!Array.isArray(weights)||!Array.isArray(values)||!values.length||weights.length<values.length||weights.length>64||weights.length%values.length||!Array.isArray(values[0])||!values[0].length||values[0].length>64)throw new RangeError("Неверное число heads/tokens");
  const n=values[0].length;if([...weights,...values].some(row=>!Array.isArray(row)||row.length!==n)||[...weights.flat(),...values.flat()].some(a=>!Number.isFinite(a)||Math.abs(a)>100)||weights.some(row=>row.some(a=>a<0)||Math.abs(row.reduce((s,a)=>s+a,0)-1)>1e-10))throw new RangeError("Неверные weights/values");
  const group=weights.length/values.length;
  return weights.map((row,h)=>row.reduce((s,a,i)=>s+a*values[Math.floor(h/group)][i],0));
