insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('bfd90acf-c4d8-413a-8f0c-6b34d0ffac0e','ba9e9e01-6659-4782-8edb-fc50b92940d7','9961e8d5897fd0ca37550465fcd5a125bfcd2593e438191ef872ed5f48537f7c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"grouped_mix"}'::jsonb,array['Sharing values не означает sharing query weights.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn grouped_mix(weights: &[Vec<f64>], values: &[Vec<f64>]) -> Result<Vec<f64>, InputError> {
    if values.is_empty()||weights.len()<values.len()||weights.len()>64||weights.len()%values.len()!=0||values[0].is_empty()||values[0].len()>64{return Err(InputError::InvalidInput);}
    let n=values[0].len();if weights.iter().chain(values).any(|row|row.len()!=n)||weights.iter().chain(values).flatten().any(|a|!a.is_finite()||a.abs()>100.0)||weights.iter().any(|row|row.iter().any(|a|*a<0.0)||(row.iter().sum::<f64>()-1.0).abs()>1e-10){return Err(InputError::InvalidInput);}
    let group=weights.len()/values.len();
    Ok(weights.iter().enumerate().map(|(h,row)|row.iter().zip(&values[h/group]).map(|(a,v)|a*v).sum()).collect())
}
','Weights [[1,0],[0,1],[.5,.5],[.25,.75]], shared values [[2,4],[10,20]] дают [2,4,15,17.5]. Q heads имеют разные weights при общей KV group.');
