insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('60826e3b-6056-4dc6-8cdf-24a927ee030f','ba9e9e01-6659-4782-8edb-fc50b92940d7','b21c43671dcad3c7e4bb1723d0bb7122f1834cd468942460e5176675041e9ff7','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"rope"}'::jsonb,array['Обе новые координаты вычисляйте из исходных a,b.']::text[],'import math

def rope(x: list[float], pos: int, base: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 2<=len(x)<=64 or len(x)%2 or not type(pos) is int or not 0<=pos<=1000000 or not _finite(base) or not 1<=base<=1000000 or any(not _finite(a) or abs(a)>100 for a in x):
        raise ValueError("RoPE требует чётную ширину и finite inputs")
    result=[]
    for i in range(0,len(x),2):
        angle=pos*base**(-i/len(x));c=math.cos(angle);s=math.sin(angle)
        result.extend([x[i]*c-x[i+1]*s,x[i]*s+x[i+1]*c])
    return result
','При pos 0 vector не меняется. Для [1,0],pos 1 получаем [cos(1),sin(1)]. Поворот сохраняет squared norm.');
