def sinusoidal_position(width: int, pos: int, base: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not type(width) is int or not 2<=width<=64 or width%2 or not type(pos) is int or not 0<=pos<=1000000 or not _finite(base) or not 1<=base<=1000000:
        raise ValueError("Неверная positional configuration")
    result=[]
    for i in range(0,width,2):
        angle=pos*base**(-i/width)
        result.extend([math.sin(angle),math.cos(angle)])
    return result
