insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('90cac68a-2680-44e5-8deb-8839ac9dcb8d','ba9e9e01-6659-4782-8edb-fc50b92940d7','a173052ff69acfc7ab5320a4e5b2aced692c337b04b578672a903e48a0e62651','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"sinusoidal_position"}'::jsonb,array['Используйте те же частоты, но другой смысл output.']::text[],'#[derive(Debug, PartialEq)]
