def layer_norm(x: list[float], eps: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1<=len(x)<=64 or any(not _finite(a) or abs(a)>10000 for a in x) or not _finite(eps) or not 1e-12<=eps<=1:
        raise ValueError("Неверная normalization")
    mean=sum(x)/len(x)
