def residual_backward(incoming: list[float], local: list[float]) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1<=len(incoming)<=64 or len(incoming)!=len(local) or any(not _finite(a) or abs(a)>10000 for a in incoming+local):
        raise ValueError("Неверные gradients")
    return [g*(1+d) for g,d in zip(incoming,local)]
