insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('a3ba3aea-077e-4f10-8f2a-01b5c2af1aa3','ba9e9e01-6659-4782-8edb-fc50b92940d7','8f1ae201e9a51bbf7d38369e002ef3d49d2037e17443ab6ff3fd72bf0c0b36ee','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"residual_backward"}'::jsonb,array['Складывайте identity gradient, а не перезаписывайте.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn residual_backward(incoming: &[f64], local: &[f64]) -> Result<Vec<f64>, InputError> {
    if incoming.is_empty()||incoming.len()>64||incoming.len()!=local.len()||incoming.iter().chain(local).any(|a|!a.is_finite()||a.abs()>10000.0){return Err(InputError::InvalidInput);}
    Ok(incoming.iter().zip(local).map(|(g,d)|g*(1.0+d)).collect())
}
','incoming=[2,3],local=[0,−1] →[2,0]. Первый identity path сохраняет gradient даже при F′=0; при F′=−1 пути взаимно уничтожаются.');
