insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('e291648d-b55d-4e7a-8e61-52d8ea8802ee','ba9e9e01-6659-4782-8edb-fc50b92940d7','a35191a47925e62f293bcb6d788b1831cedd1dfa360b8bd76a2e043743840286','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"ffn_scalar"}'::jsonb,array['Сначала preactivation,потом ReLU,потом output affine.']::text[],'import math

def ffn_scalar(x: float, w1: float, b1: float, w2: float, b2: float) -> float:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if any(not _finite(a) or abs(a)>100 for a in (x,w1,b1,w2,b2)):
