insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('c7c7924d-d599-41f2-8e75-a0225e64a68c','ba9e9e01-6659-4782-8edb-fc50b92940d7','859ec1377f363077698b63759f089f462a4b081a5a9188d2e5e847bcf8b98ac5','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"ffn_scalar"}'::jsonb,array['Сначала preactivation,потом ReLU,потом output affine.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn ffn_scalar(x: f64, w1: f64, b1: f64, w2: f64, b2: f64) -> Result<f64, InputError> {
    if [x,w1,b1,w2,b2].iter().any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}
    Ok(w2*(w1*x+b1).max(0.0)+b2)
}
