pub enum InputError { InvalidInput }
pub struct KVCache {pub keys:Vec<Vec<f64>>,pub values:Vec<Vec<f64>>}
pub fn append_cache(keys: &[Vec<f64>], values: &[Vec<f64>], new_key: &[f64], new_value: &[f64], pos: usize) -> Result<KVCache, InputError> {
    if keys.len()!=values.len()||keys.len()>=64||pos!=keys.len()||new_key.is_empty()||new_key.len()>64||new_value.is_empty()||new_value.len()>64||keys.iter().any(|k|k.len()!=new_key.len())||values.iter().any(|v|v.len()!=new_value.len())||keys.iter().chain(values).flatten().chain(new_key).chain(new_value).any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}
    let mut k=keys.to_vec();let mut v=values.to_vec();k.push(new_key.to_vec());v.push(new_value.to_vec());Ok(KVCache{keys:k,values:v})
}
','Пустой cache при pos 0 получает первую строку. При pos 1 прежний prefix сохраняется и append добавляет новую строку; произвольный pos —ошибка.');
