def scaled_attention(query: list[float], keys: list[list[float]], values: list[list[float]], allowed: list[bool]) -> dict[str, list[float]]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1<=len(query)<=64 or not 1<=len(keys)<=64 or len(keys)!=len(values) or len(keys)!=len(allowed) or not values[0] or len(values[0])>64 or any(type(a) is not bool for a in allowed) or not any(allowed):
        raise ValueError("Неверные оси/mask")
    if any(len(k)!=len(query) for k in keys) or any(len(v)!=len(values[0]) for v in values) or any(not _finite(a) or abs(a)>100 for row in [query]+keys+values for a in row):
        raise ValueError("Неверные shapes/values")
    scores=[sum(a*b for a,b in zip(query,k))/math.sqrt(len(query)) for k in keys]
    m=max(s for s,ok in zip(scores,allowed) if ok)
    e=[math.exp(s-m) if ok else 0.0 for s,ok in zip(scores,allowed)]
    total=sum(e); weights=[a/total for a in e]
    return {"weights":weights,"out":[sum(weights[j]*values[j][i] for j in range(len(keys))) for i in range(len(values[0]))]}
','Output[3],weights[.5,.5]. Cache экономит повторные K/V projections, но итоговая attention формула прежняя.');
