insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('640dc486-657a-4880-8910-ded17022248e','ba9e9e01-6659-4782-8edb-fc50b92940d7','1ad136143beca1c83ebb3df70ec6823ab955d45beacc68f536f54eadbb770e8f','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"scaled_attention"}'::jsonb,array['Cache не меняет порядок prefix.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub struct AttentionResult {pub weights:Vec<f64>,pub out:Vec<f64>}
pub fn scaled_attention(query: &[f64], keys: &[Vec<f64>], values: &[Vec<f64>], allowed: &[bool]) -> Result<AttentionResult, InputError> {
    if query.is_empty()||query.len()>64||keys.is_empty()||keys.len()>64||keys.len()!=values.len()||keys.len()!=allowed.len()||values[0].is_empty()||values[0].len()>64||!allowed.iter().any(|a|*a){return Err(InputError::InvalidInput);}
    if keys.iter().any(|k|k.len()!=query.len())||values.iter().any(|v|v.len()!=values[0].len())||query.iter().chain(keys.iter().flatten()).chain(values.iter().flatten()).any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}
    let scores:Vec<f64>=keys.iter().map(|k|query.iter().zip(k).map(|(a,b)|a*b).sum::<f64>()/(query.len() as f64).sqrt()).collect();
    let m=scores.iter().zip(allowed).filter(|(_,ok)|**ok).map(|(s,_)|*s).fold(f64::NEG_INFINITY,f64::max);
    let e:Vec<f64>=scores.iter().zip(allowed).map(|(s,ok)|if *ok{(s-m).exp()}else{0.0}).collect();let total:f64=e.iter().sum();let weights:Vec<f64>=e.iter().map(|a|a/total).collect();
    let out=(0..values[0].len()).map(|i|values.iter().zip(&weights).map(|(v,a)|a*v[i]).sum()).collect();
    Ok(AttentionResult{weights,out})
}
','Output[3],weights[.5,.5]. Cache экономит повторные K/V projections, но итоговая attention формула прежняя.');
