pub enum InputError { InvalidInput }
pub fn sampling_distribution(logits: &[f64], temperature: f64, top_k: usize, top_p: f64) -> Result<Vec<f64>, InputError> {
    if logits.is_empty()||logits.len()>64||logits.iter().any(|a|!a.is_finite()||a.abs()>100.0)||!temperature.is_finite()||!(0.1..=10.0).contains(&temperature)||top_k==0||top_k>logits.len()||!top_p.is_finite()||top_p<=0.0||top_p>1.0{return Err(InputError::InvalidInput);}
    let mut order:Vec<usize>=(0..logits.len()).collect();order.sort_by(|i,j|logits[*j].partial_cmp(&logits[*i]).unwrap().then(i.cmp(j)));order.truncate(top_k);
    let m=order.iter().map(|i|logits[*i]/temperature).fold(f64::NEG_INFINITY,f64::max);let e:Vec<f64>=order.iter().map(|i|(logits[*i]/temperature-m).exp()).collect();let total:f64=e.iter().sum();let weights:Vec<f64>=e.iter().map(|a|a/total).collect();
    let(mut count,mut cumulative)=(0,0.0);while count<order.len(){cumulative+=weights[count];count+=1;if cumulative>=top_p{break;}}
    let norm:f64=weights[..count].iter().sum();let mut result=vec![0.0;logits.len()];for j in 0..count{result[order[j]]=weights[j]/norm;}Ok(result)
}
