def sampling_distribution(logits: list[float], temperature: float, top_k: int, top_p: float) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1<=len(logits)<=64 or any(not _finite(a) or abs(a)>100 for a in logits) or not _finite(temperature) or not .1<=temperature<=10 or not type(top_k) is int or not 1<=top_k<=len(logits) or not _finite(top_p) or not 0<top_p<=1:
        raise ValueError("Неверные sampling controls")
    order=sorted(range(len(logits)),key=lambda i:(-logits[i],i))[:top_k]
    m=max(logits[i]/temperature for i in order)
    e=[math.exp(logits[i]/temperature-m) for i in order];total=sum(e)
    weights=[a/total for a in e]
    keep=[];cumulative=0.0
    for i,p in zip(order,weights):
        keep.append((i,p));cumulative+=p
        if cumulative>=top_p:break
    normalizer=sum(p for i,p in keep);result=[0.0]*len(logits)
    for i,p in keep:result[i]=p/normalizer
    return result
