insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('f841a312-f459-4b5e-87e1-4596c56db785','ba9e9e01-6659-4782-8edb-fc50b92940d7','7b19e5311e519a6353d6551e4ce2f5b165b5474dce555d53db9f25bb784e142c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"stableSoftmax"}'::jsonb,array['Из всех logits вычитайте один и тот же максимум: наибольшая экспонента станет 1.','Сначала получите весь массив exp(zᵢ−m), затем делите каждое значение на одну общую сумму.']::text[],'function stableSoftmax(logits) {
  if (!Array.isArray(logits) || logits.length < 1 || logits.length > 64 || logits.some(x => typeof x !== "number" || !Number.isFinite(x) || Math.abs(x) > 10000)) throw new RangeError("Некорректные logits");
  const maximum = Math.max(...logits);
  const weights = logits.map(x => Math.exp(x - maximum));
  const total = weights.reduce((sum, x) => sum + x, 0);
  return weights.map(x => x / total);
}
