insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('57d9561d-232c-4107-8103-1c238b774def','ba9e9e01-6659-4782-8edb-fc50b92940d7','ceea15446691696e327c2fe92cf3771cf38dedb37afa1bc8c57122370a532abc','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"stable_softmax"}'::jsonb,array['Из всех logits вычитайте один и тот же максимум: наибольшая экспонента станет 1.','Сначала получите весь массив exp(zᵢ−m), затем делите каждое значение на одну общую сумму.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn stable_softmax(logits: &[f64]) -> Result<Vec<f64>, InputError> {
    if logits.is_empty() || logits.len() > 64 || logits.iter().any(|x| !x.is_finite() || x.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    let maximum = logits.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    let weights: Vec<f64> = logits.iter().map(|x| (x - maximum).exp()).collect();
    let total: f64 = weights.iter().sum();
    Ok(weights.iter().map(|x| x / total).collect())
}
','Для [1000,1001] сдвинутые значения −1 и 0. exp(−1)/(1+exp(−1))≈0.26894. Деление logits на их сумму не сохраняет сдвиговую симметрию и может дать отрицательные веса.');
