insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('c3928e15-20a2-4ef4-8776-8ce42830214f','ba9e9e01-6659-4782-8edb-fc50b92940d7','80ff159c5f48dac910380187c913ab078b5a95bfa3407b891538ed6dc2e99e7b','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"stable_softmax"}'::jsonb,array['Проверьте отношение весов классов: exp(ln 4)/exp(ln 2)=2.','Общий сдвиг должен исчезнуть из каждой разности zᵢ−max(z).']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn stable_softmax(logits: &[f64]) -> Result<Vec<f64>, InputError> {
    if logits.is_empty() || logits.len() > 64 || logits.iter().any(|x| !x.is_finite() || x.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    let maximum = logits.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    let weights: Vec<f64> = logits.iter().map(|x| (x - maximum).exp()).collect();
    let total: f64 = weights.iter().sum();
    Ok(weights.iter().map(|x| x / total).collect())
}
','Экспоненты пропорциональны [1,2,4,2,1], сумма 10. Получатся [0.1,0.2,0.4,0.2,0.1] при обоих сдвигах. Сумма 1 сама по себе пропустила бы ошибочный всегда равномерный ответ.');
insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('45ae3f6a-065e-4fb4-8a4d-6bd16fd96ba4','e7a0df71-8f86-46bd-87c2-066290cdb858','ba9e9e01-6659-4782-8edb-fc50b92940d7','d966a9b1-083b-440e-830a-c110bd5ba9d6','unit.transformer.attention.softmax.transfer-b',2,'Контроль B · перестановка attention keys','Получите веса одной строки attention scores [ln(3),0,ln(2)] без маски. Затем переставьте keys в порядке [2,0,1] (индексы с 0). Реализуйте ту же функцию для любой длины по контракту и проверьте, что веса переставились вместе с keys. Вход: 1–64 конечных logits в пределах ±10000. Верните новый массив такой же длины, не меняя вход. Пустой, нечисловой или неконечный вход отклоняется: ValueError (wrong type допускает TypeError), RangeError или InputError. Нулевые вероятности из-за underflow допустимы. Сравнение: atol=1e−12, rtol=1e−10.

m = max(z); pᵢ = exp(zᵢ − m) / Σⱼ exp(zⱼ − m)');
