insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('8a0e47a7-9444-43ed-8425-0d355fb6b50e','ba9e9e01-6659-4782-8edb-fc50b92940d7','f48b61f1c2ab0e645d39bdea1dcd7a7ccb380a3129e0fe08b12ea04ced5cdaad','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"stable_softmax"}'::jsonb,array['Это softmax по keys одной строки, не по нескольким query одновременно.','Знаменатель суммы не меняется от перестановки; числители переезжают вместе с scores.']::text[],'import math

def stable_softmax(logits: list[float]) -> list[float]:
    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)
    if not 1 <= len(logits) <= 64 or any(not _finite(x) or abs(x) > 10000 for x in logits):
        raise ValueError("Ожидаются 1–64 конечных logits в пределах ±10000")
    m = max(logits)
    weights = [math.exp(x - m) for x in logits]
    total = sum(weights)
    return [p / total for p in weights]
','Исходные weights [1/2,1/6,1/3], переставленные [1/3,1/2,1/6]. Индекс key — порядок элемента, не новая пространственная координата.');
