insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('a18e1c8a-2b79-4d55-8817-813cc55b936a','ba9e9e01-6659-4782-8edb-fc50b92940d7','06508f0b11d7fd874a29a50ab9b2a3683f29f69ef038682d36c3fa5427859059','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Назовите каждый элемент входа по порядку, указанному в условии.','h=tanh(w_x x+w_h h_prev+b); ∂h/∂h_prev=w_h(1−h²)']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values)!=5 or any(isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v) or abs(v)>4 for v in values): raise ValueError("input")
    x,hp,wx,wh,b=values
    h=math.tanh(wx*x+wh*hp+b)
    return [h,wh*(1-h*h)]
','Нулевая сумма даёт h=0, но влияние прошлого состояния может быть ненулевым. Для входа [0,0,1,0.5,0] ожидается [0,0.5]. Один скалярный шаг tanh RNN и локальная производная, без полного BPTT.');
