insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('fcb53a49-296c-4191-8679-99e3d6a0993c','f4e1c39d-6d71-4eb5-8d17-247f62949b77','ba9e9e01-6659-4782-8edb-fc50b92940d7','fcb53a49-296c-4191-8679-99e3d6a0993c','unit.architecture.bptt.guided',0,'Вычисление · Сумма путей BPTT на двух шагах','Напишите solve(values). Вход: [x₁,x₂,h₀,w_x,w_h,y]. Все числа конечны, |v|≤4, форма точно как в примере; вход не изменять. Отклоняйте неверную форму и значения (ValueError/RangeError/Err). Ненулевое h₀ открывает оба пути влияния w_h; верните [loss,dL/dw_h]. Два шага скалярной RNN без bias; выход [loss,dL/dw_h]. Это гранулярный backward, не всё обучение последовательности. Сравнение atol=1e−10, rtol=1e−9.

h₁=tanh(w_x x₁+w_h h₀); h₂=tanh(w_x x₂+w_h h₁); L=½(h₂−y)²');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('ce0e5dec-9bb8-4e26-878c-1e13794108c6','fcb53a49-296c-4191-8679-99e3d6a0993c','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def solve(values: list[float]) -> list[float]:
