  if(!Array.isArray(values)||values.length!==6||Array.from(values).some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>4)) throw new RangeError("input");
  const [x1,x2,h0,wx,wh,y]=values;
