insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('eb257717-5d72-4bfb-8df0-aefa26344606','cedd9f42-ddbf-4bb2-8e99-b9ce42a276d8','ba9e9e01-6659-4782-8edb-fc50b92940d7','eb257717-5d72-4bfb-8df0-aefa26344606','unit.architecture.lstm.guided',0,'Вычисление · Запись и сохранение LSTM cell','Напишите solve(values). Вход: [c_prev,f,i,o,g]; f,i,o∈[0,1], g∈[−1,1]. Все числа конечны, |v|≤4, форма точно как в примере; вход не изменять. Отклоняйте неверную форму и значения (ValueError/RangeError/Err). Закрытый input gate сохраняет старую cell при f=1. Ворота уже вычислены. Нужно соединить их значения; нет вычисления четырёх affine-проекций и обучения LSTM. Сравнение atol=1e−10, rtol=1e−9.

c=f c_prev+i g; h=o tanh(c)');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('d705c970-19f8-4e8f-8764-a8e732710adb','eb257717-5d72-4bfb-8df0-aefa26344606','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def solve(values: list[float]) -> list[float]:
    raise NotImplementedError("Реализуйте формулу")
','solve','[{"input":{"values":[1,1,0,1,-1]},"output":[1,0.7615941559557649]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('d705c970-19f8-4e8f-8764-a8e732710adb','ba9e9e01-6659-4782-8edb-fc50b92940d7','162d68b1da2cb6219ffe68868108bb2c0a4c57cb63a9c57d5c99a23fef52413d','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Назовите каждый элемент входа по порядку, указанному в условии.','c=f c_prev+i g; h=o tanh(c)']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values)!=5 or any(isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v) or abs(v)>4 for v in values): raise ValueError("input")
    if any(not 0 <= v <= 1 for v in values[1:4]) or abs(values[4]) > 1: raise ValueError("gates")
    cp,f,i,o,g=values
    c=f*cp+i*g
    return [c,o*math.tanh(c)]
','Закрытый input gate сохраняет старую cell при f=1. Для входа [1,1,0,1,-1] ожидается [1,0.7615941559557649]. Ворота уже вычислены. Нужно соединить их значения; нет вычисления четырёх affine-проекций и обучения LSTM.');
