insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('c0867027-48d2-4350-8a14-1adbb3de8935','a9d30cf6-0079-46a7-8e20-a7a229705d85','ba9e9e01-6659-4782-8edb-fc50b92940d7','c0867027-48d2-4350-8a14-1adbb3de8935','unit.architecture.gru.guided',0,'Вычисление · Reset-before GRU','Напишите solve(values). Вход: [h_prev,z,r,x,w_x,w_h]; z,r∈[0,1]. Все числа конечны, |v|≤4, форма точно как в примере; вход не изменять. Отклоняйте неверную форму и значения (ValueError/RangeError/Err). При z=1 сохраняется h_prev, даже если кандидат равен 0. Reset-before и update как доля сохранения прошлого, согласовано с учебником; bias=0, нет обучения GRU. Сравнение atol=1e−10, rtol=1e−9.

g=tanh(w_x x+w_h r h_prev); h=z h_prev+(1−z)g');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('1c4aeb32-250f-4358-8117-53dba33435f2','c0867027-48d2-4350-8a14-1adbb3de8935','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def solve(values: list[float]) -> list[float]:
    raise NotImplementedError("Реализуйте формулу")
