insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('1c4aeb32-250f-4358-8117-53dba33435f2','ba9e9e01-6659-4782-8edb-fc50b92940d7','cb5aaf87151fc4ac85b90466b39ca55ca0556ad236e2a9abda7d51baa0ccc8ff','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Назовите каждый элемент входа по порядку, указанному в условии.','g=tanh(w_x x+w_h r h_prev); h=z h_prev+(1−z)g']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values)!=6 or any(isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v) or abs(v)>4 for v in values): raise ValueError("input")
    if any(not 0 <= v <= 1 for v in values[1:3]): raise ValueError("gates")
    hp,z,r,x,wx,wh=values
    g=math.tanh(wx*x+wh*r*hp)
