def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 5 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    x,w,b,u,target = values
    h = math.tanh(w*x+b)
    y = x+u*h
    d = 2*(y-target)
    a = d*u*(1-h*h)
    return [y,(y-target)**2,a*x,a,d*h,d+a*w]
