pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=5 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (x,w,b,u,target)=(values[0],values[1],values[2],values[3],values[4]);
    let h=(w*x+b).tanh(); let y=x+u*h; let d=2.0*(y-target); let a=d*u*(1.0-h*h);
    Ok(vec![y,(y-target).powi(2),a*x,a,d*h,d+a*w])
}
