insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('4c56a4fb-6de1-449c-8e9b-c9a88f983210','ba9e9e01-6659-4782-8edb-fc50b92940d7','21e1fe151503e2ab9688c5eb1d9af99ace5770e08131fc8141165350c4c47899','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['После совпадения пару надо поглотить целиком; иначе перекрывающиеся a,a в a,a,a сольются дважды.','Одно совпадение поглощает два исходных token. Разберите промежуточные величины до записи результата.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 4 <= len(values) <= 35 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    if not 4 <= len(values) <= 35 or any(v != int(v) or v < 0 for v in values) or values[2] in values[:2]:
        raise ValueError("IDs и новая пара")
    a,b,new = values[:3]
    tokens = values[3:]
    out = []
    i = 0
    while i < len(tokens):
        if i+1 < len(tokens) and tokens[i] == a and tokens[i+1] == b:
            out.append(new)
            i += 2
        else:
            out.append(tokens[i])
            i += 1
    return out
