pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if (values.len()<4 || values.len()>35) || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
