def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 2 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    a,b = values
    s = 1/(1+math.exp(-a)) if a >= 0 else math.exp(a)/(1+math.exp(a))
    return [a*s*b,b*(s+a*s*(1-s)),a*s]
