insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('2e1681a1-9ddc-4b80-8344-d32935be6f9c','ba9e9e01-6659-4782-8edb-fc50b92940d7','56389f776400c3a91abb44823abbebffbf5f23a06c31f3ee6f341e599bd5646c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Sort по убыванию вероятности, при равенстве по index. Выбранные вероятности нужно нормировать повторно.','Expert с index=2 может быть исключён даже при большом v2. Разберите промежуточные величины до записи результата.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 7 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    p = values[:3]
    if any(x < 0 for x in p) or abs(sum(p)-1)>1e-10 or values[6] not in (0,1):
        raise ValueError("probabilities/capacity")
    if values[6] == 0:
        return [0,-1,-1]
    i,j = sorted(range(3),key=lambda k:(-p[k],k))[:2]
    return [(p[i]*values[3+i]+p[j]*values[3+j])/(p[i]+p[j]),i,j]
