pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=5 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (m,l,u,s,v)=(values[0],values[1],values[2],values[3],values[4]);
    if l<0.0 || (l==0.0 && u!=0.0) {return Err(InputError);}
    let maximum=if l>0.0 {m.max(s)} else {s}; let r=if l>0.0 {(m-maximum).exp()}else{0.0}; let p=(s-maximum).exp(); let normalizer=r*l+p; let acc=r*u+p*v;
    Ok(vec![maximum,normalizer,acc,acc/normalizer])
}
