insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('438c3356-12f3-4438-84ef-bb0a93d003b1','ba9e9e01-6659-4782-8edb-fc50b92940d7','dec9d3cf1a06656c7a93621fe4ab16a6b3af081cc569e688510a964acd1dacd5','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Error считайте после global decay. Другой адрес меняется только от alpha, не от новой записи.','Error вычисляется относительно decayed памяти. Разберите промежуточные величины до записи результата.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 6 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    s0,s1,key,value,alpha,beta = values
    if key not in (0,1) or not 0 <= alpha <= 1 or not 0 <= beta <= 1:
        raise ValueError("key/gates")
    out = [alpha*s0,alpha*s1]
    k = int(key)
    e = value-out[k]
    out[k] += beta*e
    return out+[e]
','S=[2,3],key=0,value=4,alpha=.5,beta=1 → D=[1,1.5],e=3,S′=[4,1.5]. Error вычисляется относительно decayed памяти. Граница упражнения: Два ортогональных ключа, scalar value и один delta update. Selective SSM discretization, произвольные keys и полный DeltaNet не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
