insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('ba733a4b-7432-4a8b-8133-9717595873fb','ba9e9e01-6659-4782-8edb-fc50b92940d7','25bc4641cad0aa87746e241c8b5b930af4b434b8ff854620e7c8b8af92608440','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"solve"}'::jsonb,array['Error считайте после global decay. Другой адрес меняется только от alpha, не от новой записи.','Error вычисляется относительно decayed памяти. Разберите промежуточные величины до записи результата.']::text[],'#[derive(Debug, PartialEq)]
pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=6 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (k,value,alpha,beta)=(values[2],values[3],values[4],values[5]);
    if (k!=0.0 && k!=1.0) || !(0.0..=1.0).contains(&alpha) || !(0.0..=1.0).contains(&beta) {return Err(InputError);}
    let mut out=vec![alpha*values[0],alpha*values[1]]; let index=k as usize; let e=value-out[index]; out[index]+=beta*e; out.push(e);
    Ok(out)
}
','S=[2,3],key=0,value=4,alpha=.5,beta=1 → D=[1,1.5],e=3,S′=[4,1.5]. Error вычисляется относительно decayed памяти. Граница упражнения: Два ортогональных ключа, scalar value и один delta update. Selective SSM discretization, произвольные keys и полный DeltaNet не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
