insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('59663c1b-0c92-4b92-8b52-b1847c252372','ba9e9e01-6659-4782-8edb-fc50b92940d7','a48aade73f9f174e9d32c58dd37e9cd64f40b9e41c05311ada03fca31aa6c87c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"solve"}'::jsonb,array['Velocity — производная path по t, а не текущая точка x_t.','Одинаковые endpoints дают нулевую velocity при любом t. Разберите промежуточные величины до записи результата.']::text[],'#[derive(Debug, PartialEq)]
pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=3 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (a,b,t)=(values[0],values[1],values[2]);
    if !(0.0..=1.0).contains(&t) {return Err(InputError);}
    Ok(vec![(1.0-t)*a+t*b,b-a])
}
','x0=−2,x1=4,t=.25 → x_t=−.5,velocity=6. При t=0 velocity остаётся 6. Одинаковые endpoints дают нулевую velocity при любом t. Граница упражнения: Одна conditional training pair на прямом пути. Marginal field, learned velocity, Euler solver и генерация не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
