pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=6 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let k=values[4];if k!=0.0 && k!=1.0 {return Err(InputError);}
    let i=k as usize;let base=values[2]*values[0]+values[3]*values[1];let e=values[2+i]*(values[5]-values[i]);
    Ok(vec![base,base+e,e])
}
