insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('ff343452-d0fa-45e2-8590-8c5dc927fc0c','ba9e9e01-6659-4782-8edb-fc50b92940d7','43e7a465f32edb7a8210c146440bc7d0e825d154c016ad1f1bccbb33474cefb3','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Вторая sample видна через T=(1−alpha0). Остаток transmittance относится background.','T текущей sample учитывает только предыдущие samples. Разберите промежуточные величины до записи результата.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 7 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    s0,d0,c0,s1,d1,c1,bg = values
    if min(s0,d0,s1,d1)<0 or any(not 0 <= c <= 1 for c in (c0,c1,bg)):
        raise ValueError("density/delta/color")
    t0,t1 = math.exp(-s0*d0),math.exp(-s1*d1)
    t = t0*t1
