insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('f6a19624-7fc6-42ec-8061-6aa8d4923aa0','ba9e9e01-6659-4782-8edb-fc50b92940d7','9d85475ac702d250a629ed94942356a486db7cdf308adc3de8ea8cceff2f6072','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"solve"}'::jsonb,array['Вторая sample видна через T=(1−alpha0). Остаток transmittance относится background.','Разбиение при постоянной density/color сохраняет итог. Разберите промежуточные величины до записи результата.']::text[],'#[derive(Debug, PartialEq)]
pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=7 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (s0,d0,c0,s1,d1,c1,bg)=(values[0],values[1],values[2],values[3],values[4],values[5],values[6]);
    if [s0,d0,s1,d1].iter().any(|x| *x<0.0) || [c0,c1,bg].iter().any(|c| !(0.0..=1.0).contains(c)) {return Err(InputError);}
    let t0=(-s0*d0).exp();let t1=(-s1*d1).exp();let t=t0*t1;
    Ok(vec![(1.0-t0)*c0+t0*(1.0-t1)*c1+t*bg,1.0-t,t])
}
','sigma0=sigma1=ln2,delta=1,colors=[1,0],background=1: weights=.5,.25,background=.25 → color=.75,opacity=.75. Разбиение при постоянной density/color сохраняет итог. Граница упражнения: Композиция двух samples одного ray с scalar color. Neural field, обучение density и полноценное RGB изображение не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
