    let z=beta*((values[0]-values[2])-(values[1]-values[3]));let s=if z<=0.0 {1.0/(1.0+z.exp())}else{(-z).exp()/(1.0+(-z).exp())};let g=-beta*s;
    Ok(vec![(-z).max(0.0)+(-z.abs()).exp().ln_1p(),g,-g])
}
