insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('03899deb-7485-4fe7-88c0-3b42d88bef1a','ba9e9e01-6659-4782-8edb-fc50b92940d7','02526737c24b3dd101449a0875e48b666e9814e138f5fa54e2ba1210cca72a79','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Zero-point прибавляется после rounding и вычитается при dequantization. Clamp делайте до dequantization.','Tie правило должно быть одинаковым в трёх языках. Разберите промежуточные величины до записи результата.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 3 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    w,scale,zero = values
    if not 1e-6 <= scale <= 1000 or zero != int(zero) or not -8 <= zero <= 7:
        raise ValueError("metadata")
    q = min(7,max(-8,math.floor(w/scale+.5)+zero))
    y = (q-zero)*scale
    return [q,y,y-w]
