pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=2 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (p0,q0)=(values[0],values[1]);if !(0.0..=1.0).contains(&p0) || !(0.0..=1.0).contains(&q0) {return Err(InputError);}
    let p=[p0,1.0-p0];let q=[q0,1.0-q0];let a:Vec<f64>=(0..2).map(|i|if q[i]>0.0 {(p[i]/q[i]).min(1.0)}else{0.0}).collect();let mass=[(p[0]-q[0]).max(0.0),(p[1]-q[1]).max(0.0)];let z=mass[0]+mass[1];let r=if z>0.0 {[mass[0]/z,mass[1]/z]}else{p};let mut out=a;out.extend(r);out.push(z);out.extend((0..2).map(|i|p[i].min(q[i])+z*r[i]));
    Ok(out)
}
','p=[.8,.2],q=[.5,.5]: accept=[1,.4],residual=[1,0],Z=.3,exact=[.8,.2]. q_i=0 не допускает proposal данного token, поэтому не делите на ноль. Граница упражнения: Аналитическая correction law одного Bernoulli proposal. Block decoding, sampling RNG и speedup модели не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
