insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('d27ea11a-9cbe-4051-88ff-c406c82a2441','ba9e9e01-6659-4782-8edb-fc50b92940d7','2d3e45ca88eb27bfcb4fde13937acccdd0dc6c6107f0244cd30a036b375c09ab','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Сначала проверьте reachability. Недоступный key не получает маленький ненулевой вес — вес ровно 0.','Window определяет доступность отдельно от score. Разберите промежуточные величины до записи результата.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 5 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    near,far,distance,window,slope = values
    if distance != int(distance) or distance < 1 or window != int(window) or window < 0 or not 0 <= slope <= 10:
        raise ValueError("distance/window/slope")
    if distance > window:
        return [1,0]
    far -= slope*distance
    m = max(near,far)
    a,b = math.exp(near-m),math.exp(far-m)
    return [a/(a+b),b/(a+b)]
