insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('7966e5ca-7d55-4db4-825b-4ebc5c29a326','ba9e9e01-6659-4782-8edb-fc50b92940d7','c67785cd8c1416b8124a8e0a8f000027659f78d4f0038cdafe362a955ae00e21','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Сначала проверьте reachability. Недоступный key не получает маленький ненулевой вес — вес ровно 0.','ALiBi penalty уменьшает score, но сам по себе не маскирует key. Разберите промежуточные величины до записи результата.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 5 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    near,far,distance,window,slope = values
    if distance != int(distance) or distance < 1 or window != int(window) or window < 0 or not 0 <= slope <= 10:
        raise ValueError("distance/window/slope")
    if distance > window:
        return [1,0]
    far -= slope*distance
    m = max(near,far)
    a,b = math.exp(near-m),math.exp(far-m)
    return [a/(a+b),b/(a+b)]
