insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('95d116f3-6b40-407c-8f54-588b27c8b98a','ba9e9e01-6659-4782-8edb-fc50b92940d7','620af0188e845fd96114f2574c293da01f9b4d2b7e9e115913e9dfbba04ab968','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"solve"}'::jsonb,array['Сначала проверьте reachability. Недоступный key не получает маленький ненулевой вес — вес ровно 0.','ALiBi penalty уменьшает score, но сам по себе не маскирует key. Разберите промежуточные величины до записи результата.']::text[],'#[derive(Debug, PartialEq)]
pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=5 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (n,f,d,w,s)=(values[0],values[1],values[2],values[3],values[4]);
    if d.fract()!=0.0 || d<1.0 || w.fract()!=0.0 || w<0.0 || !(0.0..=10.0).contains(&s) {return Err(InputError);}
    if d>w {return Ok(vec![1.0,0.0]);}
    let far=f-s*d;let m=n.max(far);let a=(n-m).exp();let b=(far-m).exp();
    Ok(vec![a/(a+b),b/(a+b)])
}
','scoreNear=0,scoreFar=100,distance=3,window=2 → [1,0], как бы ни был высок farScore. ALiBi penalty уменьшает score, но сам по себе не маскирует key. Граница упражнения: Два past keys, sliding-window mask и линейный bias. RoPE, training extrapolation и качество retrieval длинной последовательности не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
