insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('947f4a94-33d4-44d1-895e-32be4739fd23','ba9e9e01-6659-4782-8edb-fc50b92940d7','99234de57f8b5aa0a785fb68cd4bcd041841c2bcd435e0def1a2697c26cc8fe3','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Freeze отличается от gradient: функция может вычислить dw, но delta frozen group обязана быть 0.','token=0 зануляет dw, а db зависит от ошибки. Разберите промежуточные величины до записи результата.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or len(values) != 6 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма, конечные числа, предел ±1000")
    x,w,b,target,eta,trainable = values
    if not 0 <= eta <= 1 or trainable not in (0,1):
        raise ValueError("eta/freeze")
    e = w*x+b-target
    g = 2*e
    return [e*e,g*x,g,w-eta*g*x*trainable,b-eta*g*trainable]
','token=2,w=1,b=0,target=1,eta=.1,trainable=1 → L=1,dw=4,db=2,newW=.6,newB=−.2. token=0 зануляет dw, а db зависит от ошибки. Граница упражнения: Scalar output head на уже готовом ViT token. Patch/QKV backward, grouped full training и validation новых узоров не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
