insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('80aac573-3bb6-48d2-852b-7b9798e7bbce','ba9e9e01-6659-4782-8edb-fc50b92940d7','34c14c4e92620610185815754ca19c9ee005dafa74ac6ba849ab375a9a489f9c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"solve"}'::jsonb,array['Freeze отличается от gradient: функция может вычислить dw, но delta frozen group обязана быть 0.','token=0 зануляет dw, а db зависит от ошибки. Разберите промежуточные величины до записи результата.']::text[],'#[derive(Debug, PartialEq)]
pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=6 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (x,w,b,t,eta,on)=(values[0],values[1],values[2],values[3],values[4],values[5]);
    if !(0.0..=1.0).contains(&eta) || (on!=0.0 && on!=1.0) {return Err(InputError);}
    let e=w*x+b-t;let g=2.0*e;
    Ok(vec![e*e,g*x,g,w-eta*g*x*on,b-eta*g*on])
}
','token=2,w=1,b=0,target=1,eta=.1,trainable=1 → L=1,dw=4,db=2,newW=.6,newB=−.2. token=0 зануляет dw, а db зависит от ошибки. Граница упражнения: Scalar output head на уже готовом ViT token. Patch/QKV backward, grouped full training и validation новых узоров не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
