pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=5 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (z,a,b,t,lam)=(values[0],values[1],values[2],values[3],values[4]);if !(0.0..=10.0).contains(&lam) {return Err(InputError);}
    let p=if z>=0.0 {1.0/(1.0+(-z).exp())}else{z.exp()/(1.0+z.exp())};let y=p*a+(1.0-p)*b;let balance=2.0*(p*p+(1.0-p).powi(2))-1.0;let mse=(y-t).powi(2);let g=(2.0*(y-t)*(a-b)+lam*(8.0*p-4.0))*p*(1.0-p);
