insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('e2762f7e-f12c-4e49-8fa8-86e686300b44','ba9e9e01-6659-4782-8edb-fc50b92940d7','02944f2e5f74569f78f8fbf692d59ba520455bd9579294a5db43863cf52dccfb','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"solve"}'::jsonb,array['Для учебной картинки display clipping допустим; обучение использует исходный epsilonPred.','t=0 зануляет db в этой time-linear ветке. Разберите промежуточные величины до записи результата.']::text[],'#[derive(Debug, PartialEq)]
pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()!=5 || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}
    let (x,t,w,b,e)=(values[0],values[1],values[2],values[3],values[4]);if !(0.0..=1.0).contains(&t) {return Err(InputError);}
    let p=w*x+b*t;let error=p-e;
    Ok(vec![p,error*error,2.0*error*x,2.0*error*t,p.clamp(-1.0,1.0)])
}
','noisy=2,t=.5,w=1,b=2,epsilon=1 → pred=3,error=2,L=4,dw=8,db=2,display=1. t=0 зануляет db в этой time-linear ветке. Граница упражнения: Один scalar epsilon predictor, MSE и parameter gradients. U-Net/DiT backward, noise schedule, reverse sampling и train/validation quality не реализованы. Публичные примеры и quiz служат самопроверкой, не серверным зачётом.');
