insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('9fe2ed08-004a-47a4-8721-252524574ddc','ba9e9e01-6659-4782-8edb-fc50b92940d7','eb3544083d72b71c14d0e7c0405c580f617d23c97952ad87313506870688d71c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"gaussian_parameters"}'::jsonb,array['Не путайте log variance с log sd.','У prior mu=0 и variance=1; среднее не является выборкой.']::text[],'import math

def gaussian_parameters(mu: float, log_var: float) -> list[float]:
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [mu, log_var]):
        raise ValueError("Некорректные числа")
    if not -20 <= log_var <= 20:
        raise ValueError("log_var вне [-20,20]")
    return [mu, math.exp(log_var), math.exp(log_var / 2)]
','exp(0)=1: нулевая log variance означает единичную variance. gaussian_parameters(mu,log_var) → [mu,variance,sd]; log_var∈[−20,20]. Это параметры уже вычисленного encoder; prior N(0,1) задаётся mu=0,log_var=0.');
