def latent_sample_kl(mu: float, log_var: float, epsilon: float) -> list[float]:
    raise NotImplementedError("Реализуйте формулу и проверку входа")
','latent_sample_kl','[{"input":{"mu":0,"log_var":0,"epsilon":2},"output":[2,0,1,1]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('a933cb0b-42f4-4833-838f-d06654321387','ba9e9e01-6659-4782-8edb-fc50b92940d7','d05ce39d4547592757b2a1f6e9cdcc614ef68523d25881436c547457ef7f573b','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"latent_sample_kl"}'::jsonb,array['Используйте один epsilon в обеих точках finite difference.','expm1(ℓ) устойчивее exp(ℓ)−1 при малом ℓ.']::text[],'import math

def latent_sample_kl(mu: float, log_var: float, epsilon: float) -> list[float]:
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [mu, log_var, epsilon]):
        raise ValueError("Некорректные числа")
    if not -20 <= log_var <= 20:
        raise ValueError("log_var")
    sd = math.exp(log_var / 2)
    return [mu + sd * epsilon, 0.5 * (mu * mu + math.expm1(log_var) - log_var), 1.0, sd * epsilon / 2]
','При mu=0 и variance=1 все слагаемые KL взаимно сокращаются. latent_sample_kl(mu,log_var,epsilon) → [z,KL,dz/dmu,dz/dlog_var]. log_var∈[−20,20]; epsilon фиксирован и передан извне. Один latent, KL к N(0,1).');
