insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('e44fdbeb-5564-4ae0-863e-c39f436ea689','ba9e9e01-6659-4782-8edb-fc50b92940d7','cb33d0cd026bcf49b9e5f12328afca86787bd987ab13af17fa900d5a89d35653','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"latent_sample_kl"}'::jsonb,array['Используйте один epsilon в обеих точках finite difference.','expm1(ℓ) устойчивее exp(ℓ)−1 при малом ℓ.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn latent_sample_kl(mu: f64, log_var: f64, epsilon: f64) -> Result<Vec<f64>, InputError> {
    if [mu,log_var,epsilon].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if !(-20.0..=20.0).contains(&log_var) { return Err(InputError::InvalidInput); }
    let sd = (log_var / 2.0).exp();
    Ok(vec![mu + sd * epsilon, 0.5 * (mu * mu + log_var.exp_m1() - log_var), 1.0, sd * epsilon / 2.0])
}
','Проверяем зависимость z от log_var при одном epsilon; новый шум изменил бы проверяемую функцию. latent_sample_kl(mu,log_var,epsilon) → [z,KL,dz/dmu,dz/dlog_var]. log_var∈[−20,20]; epsilon фиксирован и передан извне. Один latent, KL к N(0,1).');
