insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('10d772ea-53a9-49d1-8a6a-a455d2bae076','ba9e9e01-6659-4782-8edb-fc50b92940d7','aa70e888117ad948f84d329b4b07371f844539d0e1458a04727e7c9919e8aa64','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"vae_local_gradient"}'::jsonb,array['Сначала z, reconstruction, error; затем ветви NLL и KL.','Удерживайте epsilon фиксированным. Производные KL добавляются только в encoder-выходы.']::text[],'import math

def vae_local_gradient(mu: float, log_var: float, w: float, b: float, x: float, epsilon: float, beta: float) -> list[float]:
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [mu, log_var, w, b, x, epsilon, beta]):
        raise ValueError("Некорректные числа")
    if not -20 <= log_var <= 20 or beta < 0:
        raise ValueError("log_var или beta")
    sd = math.exp(log_var / 2)
    z = mu + sd * epsilon
    e = w * z + b - x
    kl = 0.5 * (mu * mu + math.expm1(log_var) - log_var)
    loss = 0.5 * e * e + beta * kl
    return [loss, e * w + beta * mu, e * w * sd * epsilon / 2 + beta * math.expm1(log_var) / 2, e * z, e]
','z=1, error=1; loss=.5+.5=1. NLL даёт e*w=2, KL даёт beta*mu=1. Складываем dmu=3. vae_local_gradient → [L,dmu,dlog_var,dw,db]. Decoder w*z+b, observation σ_x=1; постоянная log√(2π) опущена. log_var∈[−20,20], beta≥0. Это четыре локальные производные одного sample; encoder affine и batch update отдельно.');
