insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('356791b6-c19c-442e-876f-734a0e5951ca','ba9e9e01-6659-4782-8edb-fc50b92940d7','b85fcd41d12035dd8af887d56d22157680749c00b6e82f721645bd52ca54130e','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"posterior_moments"}'::jsonb,array['Закон полной variance: внутри компоненты плюс между средними.','Средняя variance encoder сама по себе теряет разброс mu.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn posterior_moments(mu: &[f64], sigma: &[f64]) -> Result<Vec<f64>, InputError> {
    if mu.len() > 256 || mu.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if sigma.len() > 256 || sigma.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if mu.is_empty() || mu.len() != sigma.len() || sigma.iter().any(|v| *v <= 0.0) { return Err(InputError::InvalidInput); }
    let mean = mu.iter().sum::<f64>() / mu.len() as f64;
    let variance = mu.iter().zip(sigma).map(|(m,s)| s*s + (m-mean).powi(2)).sum::<f64>() / mu.len() as f64;
    Ok(vec![mean, variance])
}
','Внутри каждой Gaussian variance=1, между средними ещё 1. Сумма 2. posterior_moments(mu,sigma) → [mean,variance] равновесной смеси Gaussian. Непустые равные длины, sigma_i>0. Это диагностика первых двух моментов, не тест равенства распределений или качество генерации.');
insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('707b8e16-04f2-4b1e-8fbd-2c36be0e9e93','e719a2bc-47de-4add-8d3f-f0371787b9cd','ba9e9e01-6659-4782-8edb-fc50b92940d7','ac7e7459-e937-4dff-8b65-30723c15d115','unit.vae.limits.transfer-a',1,'Перенос A · Смещённые codes','Одинаковые mu=3 имеют нулевой межкомпонентный разброс; сохраните внутреннюю variance. posterior_moments(mu,sigma) → [mean,variance] равновесной смеси Gaussian. Непустые равные длины, sigma_i>0. Это диагностика первых двух моментов, не тест равенства распределений или качество генерации. Все числовые входы конечны и по модулю ≤10000; векторы содержат не более 256 элементов. Неверный тип или область: ValueError/TypeError в Python, RangeError в JavaScript, InputError в Rust. Вход не изменять. Ответ — новый вектор в указанном порядке; atol=1e−12, rtol=1e−10. Реализуйте функцию для всех допустимых входов; открытый пример не является полным решением.

m=mean(μᵢ); Var(z)=mean(σᵢ²+(μᵢ−m)²)');
