insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('75d274ec-3cea-4afc-84fd-fe004909e151','ba9e9e01-6659-4782-8edb-fc50b92940d7','f0d736075a3cc9d308a7b72743f40c7d989568e091c2b989520881b8ce059d07','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"posterior_moments"}'::jsonb,array['Закон полной variance: внутри компоненты плюс между средними.','Средняя variance encoder сама по себе теряет разброс mu.']::text[],'import math

def posterior_moments(mu: list[float], sigma: list[float]) -> list[float]:
    if not isinstance(mu, (list, tuple)) or len(mu) > 256:
        raise ValueError("Некорректный вектор mu")
    if not isinstance(sigma, (list, tuple)) or len(sigma) > 256:
        raise ValueError("Некорректный вектор sigma")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [*mu, *sigma]):
        raise ValueError("Некорректные числа")
    if not mu or len(mu) != len(sigma) or any(v <= 0 for v in sigma):
        raise ValueError("Формы и sigma > 0")
    mean = sum(mu) / len(mu)
    variance = sum(sd * sd + (m - mean) ** 2 for m, sd in zip(mu, sigma)) / len(mu)
    return [mean, variance]
','Mean=3 и variance=.25 отличаются от prior с mean=0,variance=1. posterior_moments(mu,sigma) → [mean,variance] равновесной смеси Gaussian. Непустые равные длины, sigma_i>0. Это диагностика первых двух моментов, не тест равенства распределений или качество генерации.');
