insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('f6c8bcd9-b293-4bac-86fb-422f385fac18','ba9e9e01-6659-4782-8edb-fc50b92940d7','e32f9e9ac118e2653284ca9f1db67e8481327fb334481873af7c94e2578b0551','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"posterior_moments"}'::jsonb,array['Закон полной variance: внутри компоненты плюс между средними.','Средняя variance encoder сама по себе теряет разброс mu.']::text[],'function posterior_moments(mu, sigma) {
  if (!Array.isArray(mu) || mu.length > 256) throw new RangeError("Некорректный вектор");
  if (!Array.isArray(sigma) || sigma.length > 256) throw new RangeError("Некорректный вектор");
  if ([...mu,...sigma].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректные числа");
  if (!mu.length || mu.length !== sigma.length || sigma.some(v => v <= 0)) throw new RangeError("Формы и sigma");
  const mean = mu.reduce((a,b) => a+b, 0) / mu.length;
  return [mean, mu.reduce((a,m,i) => a + sigma[i] ** 2 + (m-mean) ** 2, 0) / mu.length];
}
','Mean=3 и variance=.25 отличаются от prior с mean=0,variance=1. posterior_moments(mu,sigma) → [mean,variance] равновесной смеси Gaussian. Непустые равные длины, sigma_i>0. Это диагностика первых двух моментов, не тест равенства распределений или качество генерации.');
