insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('76150717-56e6-4f73-81f1-48a6e935e13d','ba9e9e01-6659-4782-8edb-fc50b92940d7','b5e8cc25383dea5821d3794edd428efdef30a7b799d0b91ac98b990a592a0938','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"posterior_moments"}'::jsonb,array['Закон полной variance: внутри компоненты плюс между средними.','Средняя variance encoder сама по себе теряет разброс mu.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn posterior_moments(mu: &[f64], sigma: &[f64]) -> Result<Vec<f64>, InputError> {
    if mu.len() > 256 || mu.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if sigma.len() > 256 || sigma.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if mu.is_empty() || mu.len() != sigma.len() || sigma.iter().any(|v| *v <= 0.0) { return Err(InputError::InvalidInput); }
    let mean = mu.iter().sum::<f64>() / mu.len() as f64;
    let variance = mu.iter().zip(sigma).map(|(m,s)| s*s + (m-mean).powi(2)).sum::<f64>() / mu.len() as f64;
    Ok(vec![mean, variance])
}
','Mean=3 и variance=.25 отличаются от prior с mean=0,variance=1. posterior_moments(mu,sigma) → [mean,variance] равновесной смеси Gaussian. Непустые равные длины, sigma_i>0. Это диагностика первых двух моментов, не тест равенства распределений или качество генерации.');
