insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('f8435c48-ed52-4ff7-860c-339a13b30e3f','62274919-efd0-4c73-8ee3-c8a645f033d5','ba9e9e01-6659-4782-8edb-fc50b92940d7','f8435c48-ed52-4ff7-860c-339a13b30e3f','unit.gan.game.guided',0,'По шагам · Нейтральный D','Найдите fake и вероятность, когда logit D равен нулю. affine_gan_forward(z,g,b,d,c) → [fake,logit,probability]. G=g*z+b; D=sigmoid(d*x+c). Здесь две affine модели; скрытые слои урока не реализуются. Все числовые входы конечны и по модулю ≤10000; векторы содержат не более 256 элементов. Неверный тип или область: ValueError/TypeError в Python, RangeError в JavaScript, InputError в Rust. Вход не изменять. Ответ — новый вектор в указанном порядке; atol=1e−12, rtol=1e−10. Реализуйте функцию для всех допустимых входов; открытый пример не является полным решением.

fake=gz+b; a=d·fake+c; D=σ(a)');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('60ebc56d-e92d-4051-8935-6db7eb1103ea','f8435c48-ed52-4ff7-860c-339a13b30e3f','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def affine_gan_forward(z: float, g: float, b: float, d: float, c: float) -> list[float]:
    raise NotImplementedError("Реализуйте формулу и проверку входа")
','affine_gan_forward','[{"input":{"z":2,"g":1,"b":1,"d":0,"c":0},"output":[3,0,0.5]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('60ebc56d-e92d-4051-8935-6db7eb1103ea','ba9e9e01-6659-4782-8edb-fc50b92940d7','edb285c0bc27606d7f426649ca3d2005be4c4b12463bc7bd4fb434d91eb53768','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"affine_gan_forward"}'::jsonb,array['Две группы параметров: [g,b] и [d,c].','Sigmoid применяется к D-logit, не к выходу G.']::text[],'import math

def affine_gan_forward(z: float, g: float, b: float, d: float, c: float) -> list[float]:
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [z, g, b, d, c]):
        raise ValueError("Некорректные числа")
    fake = g * z + b
    logit = d * fake + c
    p = 1 / (1 + math.exp(-logit)) if logit >= 0 else math.exp(logit) / (1 + math.exp(logit))
    return [fake, logit, p]
','Sigmoid(0)=.5 независимо от sample; это не измерение coverage. affine_gan_forward(z,g,b,d,c) → [fake,logit,probability]. G=g*z+b; D=sigmoid(d*x+c). Здесь две affine модели; скрытые слои урока не реализуются.');
