insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('b19b0575-10ba-4454-8b9e-e54c1124edf8','59b4fd8f-06c5-4f94-8bbf-d314081e236d','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

