pub enum InputError { InvalidInput }
pub fn affine_gan_step(parameters: &[f64], real: f64, z: f64, eta_d: f64, eta_g: f64) -> Result<Vec<f64>, InputError> {
    if parameters.len() > 256 || parameters.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
