    let (g,b,d,c) = (parameters[0],parameters[1],parameters[2],parameters[3]);
    let sigmoid = |a:f64| if a >= 0.0 {1.0/(1.0+(-a).exp())} else {a.exp()/(1.0+a.exp())};
    let fake = g*z+b; let r = -sigmoid(-(d*real+c)); let f = sigmoid(d*fake+c);
    let dn = d-eta_d*(r*real+f*fake); let cn = c-eta_d*(r+f);
    let q = -sigmoid(-(dn*fake+cn))*dn;
    Ok(vec![g-eta_g*q*z,b-eta_g*q,dn,cn])
}
