insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('b0961a31-2c29-4251-84c7-856460672834','ba9e9e01-6659-4782-8edb-fc50b92940d7','453c58473f5697c1cd7cae2b437b5bc74b014a880c5c5423e8cadaaf12e8d203','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"two_region_coverage"}'::jsonb,array['Считайте попадания в обе области отдельно.','Population variance делится на N, не на N−1.']::text[],'function two_region_coverage(samples) {
  if (!Array.isArray(samples) || samples.length > 256) throw new RangeError("Некорректный вектор");
  if ([...samples].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректные числа");
  if (!samples.length) throw new RangeError("Пустая выборка");
  const left = samples.filter(v => v >= -1.5 && v <= -.5).length, right = samples.filter(v => v >= .5 && v <= 1.5).length;
  const mean = samples.reduce((a,b)=>a+b,0)/samples.length;
  return [left,right,(Number(left>0)+Number(right>0))/2,samples.reduce((a,v)=>a+(v-mean)**2,0)/samples.length];
}
','Обе из двух областей посещены: 2/2=1. Variance выборки равна 1. two_region_coverage(samples) → [left_count,right_count,coverage,population_variance]. Непустая выборка; области [−1.5,−.5] и [.5,1.5], границы включены. Coverage — доля посещённых областей, не likelihood.');
