insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('c72070f1-8e72-4edd-8b94-6f6007a10804','ba9e9e01-6659-4782-8edb-fc50b92940d7','518d0dae001c192b79f99a6eb48ace8338c65241c9e8e96a961876cf21bcc5dd','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"two_region_coverage"}'::jsonb,array['Считайте попадания в обе области отдельно.','Population variance делится на N, не на N−1.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn two_region_coverage(samples: &[f64]) -> Result<Vec<f64>, InputError> {
    if samples.len() > 256 || samples.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if samples.is_empty() { return Err(InputError::InvalidInput); }
    let left = samples.iter().filter(|v| (-1.5..=-0.5).contains(*v)).count();
    let right = samples.iter().filter(|v| (0.5..=1.5).contains(*v)).count();
    let mean = samples.iter().sum::<f64>()/samples.len() as f64;
    Ok(vec![left as f64,right as f64,((left>0) as u8+(right>0) as u8) as f64/2.0,samples.iter().map(|v|(v-mean).powi(2)).sum::<f64>()/samples.len() as f64])
}
','Обе из двух областей посещены: 2/2=1. Variance выборки равна 1. two_region_coverage(samples) → [left_count,right_count,coverage,population_variance]. Непустая выборка; области [−1.5,−.5] и [.5,1.5], границы включены. Coverage — доля посещённых областей, не likelihood.');
