insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('6c1c4b9a-7636-459e-842a-297ad4f70ee1','ba9e9e01-6659-4782-8edb-fc50b92940d7','ccd5d6396c3e8f2d39d370a7e361564fa83a06c8a7503733669805f5f1feb873','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"critic_objective"}'::jsonb,array['Critic output не вероятность, sigmoid не нужен.','Это цели для минимизации; знак real-score отрицательный.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn critic_objective(real_scores: &[f64], fake_scores: &[f64]) -> Result<Vec<f64>, InputError> {
    if real_scores.len() > 256 || real_scores.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if fake_scores.len() > 256 || fake_scores.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if real_scores.is_empty() || fake_scores.is_empty() { return Err(InputError::InvalidInput); }
    let r = real_scores.iter().sum::<f64>()/real_scores.len() as f64;
    let f = fake_scores.iter().sum::<f64>()/fake_scores.len() as f64;
    Ok(vec![f-r,-f])
}
','Минимизация fake−real увеличивает gap real−fake. Scores не ограничены вероятностным интервалом. critic_objective(real_scores,fake_scores) → [L_D,L_G], обе выборки непустые, длины могут различаться. Scores произвольные конечные числа. Только арифметика целей; Lipschitz, gradient penalty и conditional trainer здесь не реализованы.');
insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('83a614c9-9bee-4b89-8c96-4761c48bf4c3','6eaea985-f02a-4080-80bc-cbd5722e907a','ba9e9e01-6659-4782-8edb-fc50b92940d7','4fa0d538-a30c-4fa6-8138-3407ebae4481','unit.gan.variants.transfer-a',1,'Перенос A · Общий сдвиг scores','Прибавьте 10 ко всем scores; сравните L_D и L_G. critic_objective(real_scores,fake_scores) → [L_D,L_G], обе выборки непустые, длины могут различаться. Scores произвольные конечные числа. Только арифметика целей; Lipschitz, gradient penalty и conditional trainer здесь не реализованы. Все числовые входы конечны и по модулю ≤10000; векторы содержат не более 256 элементов. Неверный тип или область: ValueError/TypeError в Python, RangeError в JavaScript, InputError в Rust. Вход не изменять. Ответ — новый вектор в указанном порядке; atol=1e−12, rtol=1e−10. Реализуйте функцию для всех допустимых входов; открытый пример не является полным решением.

L_D=mean(C(fake))−mean(C(real)); L_G=−mean(C(fake))');
