insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('55e27c63-993b-4630-8279-a1b7da93a641','c949350c-6119-4fbb-8959-713485f94520','ba9e9e01-6659-4782-8edb-fc50b92940d7','55e27c63-993b-4630-8279-a1b7da93a641','unit.diffusion.training.guided',0,'По шагам · Loss и каждый gradient','Посчитайте ошибку noise predictions и производные. epsilon_mse_gradient(predicted,epsilon) → [mean_loss,d_pred_0,…]. Непустые векторы одинаковой длины. Target — переданный noise epsilon, не x0. Backward по параметрам denoiser — отдельная следующая цепочка. Все числовые входы конечны и по модулю ≤10000; векторы содержат не более 256 элементов. Неверный тип или область: ValueError/TypeError в Python, RangeError в JavaScript, InputError в Rust. Вход не изменять. Ответ — новый вектор в указанном порядке; atol=1e−12, rtol=1e−10. Реализуйте функцию для всех допустимых входов; открытый пример не является полным решением.

L=mean((ε̂ᵢ−εᵢ)²); ∂L/∂ε̂ᵢ=2(ε̂ᵢ−εᵢ)/N');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('f53cf68e-abfa-414e-83d3-c3d70203ae01','55e27c63-993b-4630-8279-a1b7da93a641','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

