insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('c5a06420-bdb6-4c51-8b21-6d88e6fa419f','ba9e9e01-6659-4782-8edb-fc50b92940d7','497da5d638e1ea31fe3e3fdc9388ec5bea5a221dcff2d622fa1fca402c6c88a2','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"epsilon_mse_gradient"}'::jsonb,array['Фиксируйте t и epsilon во время gradient check.','Mean reduction влияет на каждую производную.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn epsilon_mse_gradient(predicted: &[f64], epsilon: &[f64]) -> Result<Vec<f64>, InputError> {
    if predicted.len() > 256 || predicted.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if epsilon.len() > 256 || epsilon.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if predicted.is_empty() || predicted.len() != epsilon.len() { return Err(InputError::InvalidInput); }
    let e: Vec<f64> = predicted.iter().zip(epsilon).map(|(p,t)|p-t).collect();
    let n = e.len() as f64;
    let mut out = vec![e.iter().map(|v|v*v).sum::<f64>()/n];
    out.extend(e.iter().map(|v|2.0*v/n));
    Ok(out)
}
','Для первой ошибки 1 derivative 2·1/2=1. Mean loss=(1+4)/2=2.5. epsilon_mse_gradient(predicted,epsilon) → [mean_loss,d_pred_0,…]. Непустые векторы одинаковой длины. Target — переданный noise epsilon, не x0. Backward по параметрам denoiser — отдельная следующая цепочка.');
