insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('36417afd-368d-4a80-8cc0-bbd2fa091a87','ba9e9e01-6659-4782-8edb-fc50b92940d7','bfa2679561be5aaf70c44f9d6da163a3e2db71eae1bc82913fd694bf56be34d6','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"epsilon_mse_gradient"}'::jsonb,array['Фиксируйте t и epsilon во время gradient check.','Mean reduction влияет на каждую производную.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn epsilon_mse_gradient(predicted: &[f64], epsilon: &[f64]) -> Result<Vec<f64>, InputError> {
    if predicted.len() > 256 || predicted.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if epsilon.len() > 256 || epsilon.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if predicted.is_empty() || predicted.len() != epsilon.len() { return Err(InputError::InvalidInput); }
    let e: Vec<f64> = predicted.iter().zip(epsilon).map(|(p,t)|p-t).collect();
    let n = e.len() as f64;
    let mut out = vec![e.iter().map(|v|v*v).sum::<f64>()/n];
    out.extend(e.iter().map(|v|2.0*v/n));
    Ok(out)
}
','Loss остаётся 2.5; gradient каждого отдельного prediction вдвое меньше из-за нового N=4. epsilon_mse_gradient(predicted,epsilon) → [mean_loss,d_pred_0,…]. Непустые векторы одинаковой длины. Target — переданный noise epsilon, не x0. Backward по параметрам denoiser — отдельная следующая цепочка.');
