pub enum InputError { InvalidInput }
pub fn ddpm_scalar_step(beta: f64, previous_bar: f64, xt: f64, epsilon: f64, noise: f64) -> Result<Vec<f64>, InputError> {
    if [beta,previous_bar,xt,epsilon,noise].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if beta < 1e-6 || beta > 1.0-1e-6 || previous_bar < 1e-6 || previous_bar > 1.0 { return Err(InputError::InvalidInput); }
    let alpha = 1.0-beta; let bar = alpha*previous_bar;
    let mean = (xt-beta*epsilon/(1.0-bar).sqrt())/alpha.sqrt();
    let variance = beta*(1.0-previous_bar)/(1.0-bar);
    Ok(vec![mean,variance,mean+variance.sqrt()*noise])
}
