insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('910af585-6b9e-46a4-836a-c31b5ca1a861','ba9e9e01-6659-4782-8edb-fc50b92940d7','decc79a1876e253f1e56bcbc1f5a4d4c1b1f19e3fb9ed23632837e3ddcb98e02','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"classifier_free_guidance"}'::jsonb,array['s=0 оставляет unconditional; s=1 даёт conditional.','s>1 — экстраполяция, а не усреднение вероятностей.']::text[],'import math

def classifier_free_guidance(unconditional: list[float], conditional: list[float], scale: float) -> list[float]:
    if not isinstance(unconditional, (list, tuple)) or len(unconditional) > 256:
        raise ValueError("Некорректный вектор unconditional")
    if not isinstance(conditional, (list, tuple)) or len(conditional) > 256:
        raise ValueError("Некорректный вектор conditional")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [scale, *unconditional, *conditional]):
        raise ValueError("Некорректные числа")
    if not unconditional or len(unconditional) != len(conditional) or not 0 <= scale <= 20:
        raise ValueError("Формы или scale")
    return [u+scale*(c-u) for u,c in zip(unconditional,conditional)]
','Вклад разности умножается на 0, остаётся epsilon_u. classifier_free_guidance(unconditional,conditional,scale) → guided epsilon. Векторы непустые и одной длины, scale∈[0,20]. Это смешивание predictions, не обучение conditioner и не density.');
