  if (!Array.isArray(unconditional) || unconditional.length > 256) throw new RangeError("Некорректный вектор");
  if (!Array.isArray(conditional) || conditional.length > 256) throw new RangeError("Некорректный вектор");
  if ([scale,...unconditional,...conditional].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректные числа");
  if (!unconditional.length || unconditional.length !== conditional.length || scale < 0 || scale > 20) throw new RangeError("Формы или scale");
  return unconditional.map((u,i)=>u+scale*(conditional[i]-u));
}
