insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('fc5c2273-372f-4044-823d-37656ba5089d','86338ad5-ebc5-47ba-827c-4901022ecb99','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def self_loop_degrees(adjacency: list[float]) -> list[float]:
