','self_loop_degrees','[{"input":{"adjacency":[0,1,1,0]},"output":[2,2]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('fc5c2273-372f-4044-823d-37656ba5089d','ba9e9e01-6659-4782-8edb-fc50b92940d7','593112f288d2390cd00977b59d2d2bce11eb6bc43499526b34e8367dbf62545b','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"self_loop_degrees"}'::jsonb,array['N — квадратный корень длины, форма должна быть точной.','Изолированному узлу добавляется собственное сообщение со степенью 1.']::text[],'import math

def self_loop_degrees(adjacency: list[float]) -> list[float]:
    if not isinstance(adjacency, (list, tuple)) or len(adjacency) > 256:
        raise ValueError("Некорректный вектор adjacency")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [*adjacency]):
        raise ValueError("Некорректные числа")
    n = math.isqrt(len(adjacency))
    if n == 0 or n*n != len(adjacency) or any(v not in (0,1) for v in adjacency) or any(adjacency[i*n+j] != adjacency[j*n+i] for i in range(n) for j in range(n)):
        raise ValueError("Нужен простой неориентированный граф")
    a = [[1.0 if i == j else adjacency[i*n+j] for j in range(n)] for i in range(n)]
    d = [sum(row) for row in a]
    return d
