insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('9c7bbdb4-4e17-48be-8226-13a3a01cd585','ba9e9e01-6659-4782-8edb-fc50b92940d7','9440ccfd9c51c0ccc4a56b5b9f008fe7f6a3d6fe2826e8073a955255218c6ce1','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"self_loop_degrees"}'::jsonb,array['N — квадратный корень длины, форма должна быть точной.','Изолированному узлу добавляется собственное сообщение со степенью 1.']::text[],'import math

def self_loop_degrees(adjacency: list[float]) -> list[float]:
    if not isinstance(adjacency, (list, tuple)) or len(adjacency) > 256:
        raise ValueError("Некорректный вектор adjacency")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [*adjacency]):
        raise ValueError("Некорректные числа")
    n = math.isqrt(len(adjacency))
    if n == 0 or n*n != len(adjacency) or any(v not in (0,1) for v in adjacency) or any(adjacency[i*n+j] != adjacency[j*n+i] for i in range(n) for j in range(n)):
        raise ValueError("Нужен простой неориентированный граф")
    a = [[1.0 if i == j else adjacency[i*n+j] for j in range(n)] for i in range(n)]
    d = [sum(row) for row in a]
    return d
','Единственный входящий вклад — собственная единичная петля. self_loop_degrees(adjacency) → степени. Adjacency — row-major плоский N×N, N≥1, значения 0/1, симметричен. Установите диагональ в 1 (существующая петля не удваивается). Это явная конвенция простого графа.');
