def symmetric_aggregate(adjacency: list[float], features: list[float]) -> list[float]:
    if not isinstance(adjacency, (list, tuple)) or len(adjacency) > 256:
        raise ValueError("Некорректный вектор adjacency")
    if not isinstance(features, (list, tuple)) or len(features) > 256:
        raise ValueError("Некорректный вектор features")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [*adjacency, *features]):
        raise ValueError("Некорректные числа")
    n = math.isqrt(len(adjacency))
    if n == 0 or n*n != len(adjacency) or any(v not in (0,1) for v in adjacency) or any(adjacency[i*n+j] != adjacency[j*n+i] for i in range(n) for j in range(n)):
        raise ValueError("Нужен простой неориентированный граф")
    a = [[1.0 if i == j else adjacency[i*n+j] for j in range(n)] for i in range(n)]
    d = [sum(row) for row in a]
    if len(features) != n:
        raise ValueError("Один feature на узел")
    return [sum(a[i][j]*features[j]/math.sqrt(d[i]*d[j]) for j in range(n)) for i in range(n)]
