  if (!Array.isArray(logits) || logits.length > 256) throw new RangeError("Некорректный вектор");
  if (!Array.isArray(labels) || labels.length > 256) throw new RangeError("Некорректный вектор");
  if (!Array.isArray(mask) || mask.length > 256) throw new RangeError("Некорректный вектор");
  if ([...logits,...labels,...mask].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректные числа");
  if (!logits.length || labels.length !== logits.length || mask.length !== logits.length || [...labels,...mask].some(v=>v!==0 && v!==1) || !mask.some(v=>v===1)) throw new RangeError("Формы, labels, mask");
  const n = mask.reduce((a,b)=>a+b,0);
  const loss = logits.reduce((a,z,i)=>a+mask[i]*(Math.max(z,0)-labels[i]*z+Math.log1p(Math.exp(-Math.abs(z))))/n,0);
  return [loss,...logits.map((z,i)=>{const p=z>=0?1/(1+Math.exp(-z)):Math.exp(z)/(1+Math.exp(z));const q=z<=0?-1/(1+Math.exp(z)):-Math.exp(-z)/(1+Math.exp(-z));return mask[i]*(labels[i]===1?q:p)/n;})];
}
