insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('8874c8af-e69f-4da7-8e50-43470cad64f1','ba9e9e01-6659-4782-8edb-fc50b92940d7','c4480d62fea046cc85b41f642ff8c78d59ae8451ee45115fa4c3bafdf44fdd5d','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"masked_binary_ce"}'::jsonb,array['Held-out узлы могут участвовать в message passing, но не в supervised loss.','Нормируйте числом train nodes, а не всех nodes.']::text[],'import math

def masked_binary_ce(logits: list[float], labels: list[float], mask: list[float]) -> list[float]:
    if not isinstance(logits, (list, tuple)) or len(logits) > 256:
        raise ValueError("Некорректный вектор logits")
    if not isinstance(labels, (list, tuple)) or len(labels) > 256:
        raise ValueError("Некорректный вектор labels")
    if not isinstance(mask, (list, tuple)) or len(mask) > 256:
        raise ValueError("Некорректный вектор mask")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [*logits, *labels, *mask]):
        raise ValueError("Некорректные числа")
    if not logits or len(labels) != len(logits) or len(mask) != len(logits) or any(v not in (0,1) for v in labels+mask) or sum(mask) == 0:
        raise ValueError("Формы, бинарные метки/mask, непустой train")
    n = sum(mask)
    loss = 0.0
    grad = []
    for z,y,m in zip(logits,labels,mask):
        loss += m*(max(z,0)-y*z+math.log1p(math.exp(-abs(z))))/n
        p = 1/(1+math.exp(-z)) if z >= 0 else math.exp(z)/(1+math.exp(z))
        q = -1/(1+math.exp(z)) if z <= 0 else -math.exp(-z)/(1+math.exp(-z))
        grad.append(m*(q if y == 1 else p)/n)
    return [loss]+grad
','Mask исключает held-out label из суммы; train loss и gradients сохраняются. masked_binary_ce(logits,labels,mask) → [mean_loss,dlogit_0,…]. Непустые равные длины; labels и mask — числа 0/1, mask содержит хотя бы 1. Один binary logit равносилен двум logits [0,z]. Это loss и его локальный backward, не весь двухслойный GCN.');
