insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('be3b24a6-d610-4930-8da4-d8ffbfaff505','ba9e9e01-6659-4782-8edb-fc50b92940d7','1c678e15f8cd5726067889182ecf275927fbcc27570b15da7fb799ac306e48e5','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"masked_binary_ce"}'::jsonb,array['Held-out узлы могут участвовать в message passing, но не в supervised loss.','Нормируйте числом train nodes, а не всех nodes.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn masked_binary_ce(logits: &[f64], labels: &[f64], mask: &[f64]) -> Result<Vec<f64>, InputError> {
    if logits.len() > 256 || logits.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if labels.len() > 256 || labels.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if mask.len() > 256 || mask.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if logits.is_empty() || labels.len()!=logits.len() || mask.len()!=logits.len() || labels.iter().chain(mask).any(|v|*v!=0.0 && *v!=1.0) || !mask.contains(&1.0) { return Err(InputError::InvalidInput); }
    let n: f64 = mask.iter().sum();
    let loss: f64 = logits.iter().enumerate().map(|(i,z)|mask[i]*(z.max(0.0)-labels[i]*z+(-z.abs()).exp().ln_1p())/n).sum();
    let mut out = vec![loss];
    out.extend(logits.iter().enumerate().map(|(i,z)|{let p=if *z>=0.0 {1.0/(1.0+(-z).exp())} else {z.exp()/(1.0+z.exp())}; let q=if *z<=0.0 {-1.0/(1.0+z.exp())} else {-(-z).exp()/(1.0+(-z).exp())};mask[i]*(if labels[i]==1.0 {q} else {p})/n}));
    Ok(out)
}
','Mask исключает held-out label из суммы; train loss и gradients сохраняются. masked_binary_ce(logits,labels,mask) → [mean_loss,dlogit_0,…]. Непустые равные длины; labels и mask — числа 0/1, mask содержит хотя бы 1. Один binary logit равносилен двум logits [0,z]. Это loss и его локальный backward, не весь двухслойный GCN.');
