insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('8d4e3966-3c6e-4977-8104-e525aa56e002','291744e2-20ac-4cbc-84d0-ade0a43d768a','ba9e9e01-6659-4782-8edb-fc50b92940d7','8d4e3966-3c6e-4977-8104-e525aa56e002','unit.gnn.depth.guided',0,'По шагам · Два шага на паре','Повторите aggregation дважды и проверьте неподвижность среднего. repeat_smoothing(adjacency,features,steps) → S^steps·features. Контракт графа как symmetric_aggregate; steps целое в [0,100]. Каждый шаг синхронный, использует весь прежний вектор. Нет обучаемых W и activation. Все числовые входы конечны и по модулю ≤10000; векторы содержат не более 256 элементов. Неверный тип или область: ValueError/TypeError в Python, RangeError в JavaScript, InputError в Rust. Вход не изменять. Ответ — новый вектор в указанном порядке; atol=1e−12, rtol=1e−10. Реализуйте функцию для всех допустимых входов; открытый пример не является полным решением.

h⁽ᵏ⁺¹⁾=S h⁽ᵏ⁾; при k=0 возвращается копия h');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('cd306a04-eefd-45a3-80e4-ffb4814552c8','8d4e3966-3c6e-4977-8104-e525aa56e002','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def repeat_smoothing(adjacency: list[float], features: list[float], steps: float) -> list[float]:
