insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('fda96509-6372-4b1b-8e33-fd51966d39d6','ba9e9e01-6659-4782-8edb-fc50b92940d7','0a8d46b2e7f4bbb0e42078e8a5968a98743bdf822c852ba3e148b9c4c78477fd','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"repeat_smoothing"}'::jsonb,array['Сначала вычислите новый вектор целиком.','В нерегулярном графе стационарные raw features пропорциональны √degree, не обязательно одинаковы.']::text[],'import math

def repeat_smoothing(adjacency: list[float], features: list[float], steps: float) -> list[float]:
    if not isinstance(adjacency, (list, tuple)) or len(adjacency) > 256:
        raise ValueError("Некорректный вектор adjacency")
    if not isinstance(features, (list, tuple)) or len(features) > 256:
        raise ValueError("Некорректный вектор features")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [steps, *adjacency, *features]):
        raise ValueError("Некорректные числа")
    n = math.isqrt(len(adjacency))
    if n == 0 or n*n != len(adjacency) or any(v not in (0,1) for v in adjacency) or any(adjacency[i*n+j] != adjacency[j*n+i] for i in range(n) for j in range(n)):
        raise ValueError("Нужен простой неориентированный граф")
    a = [[1.0 if i == j else adjacency[i*n+j] for j in range(n)] for i in range(n)]
    d = [sum(row) for row in a]
    if len(features) != n or steps != int(steps) or not 0 <= steps <= 100:
        raise ValueError("Features или steps")
    h = list(features)
    for _ in range(int(steps)):
        h = [sum(a[i][j]*h[j]/math.sqrt(d[i]*d[j]) for j in range(n)) for i in range(n)]
    return h
','Без ребра нет пути передачи features. Каждая компонента сохраняет собственное состояние. repeat_smoothing(adjacency,features,steps) → S^steps·features. Контракт графа как symmetric_aggregate; steps целое в [0,100]. Каждый шаг синхронный, использует весь прежний вектор. Нет обучаемых W и activation.');
