insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('dcae5a05-5546-470d-8c20-ce826353e2e6','ba9e9e01-6659-4782-8edb-fc50b92940d7','f182e2fe28aacd91b1ca78bf3bb76a7ff9708ea25d068b223de43b425350fc86','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"repeat_smoothing"}'::jsonb,array['Сначала вычислите новый вектор целиком.','В нерегулярном графе стационарные raw features пропорциональны √degree, не обязательно одинаковы.']::text[],'function repeat_smoothing(adjacency, features, steps) {
  if (!Array.isArray(adjacency) || adjacency.length > 256) throw new RangeError("Некорректный вектор");
  if (!Array.isArray(features) || features.length > 256) throw new RangeError("Некорректный вектор");
  if ([steps,...adjacency,...features].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректные числа");
  const n = Math.sqrt(adjacency.length);
  if (!n || !Number.isInteger(n) || adjacency.some(v=>v!==0 && v!==1) || adjacency.some((v,k)=>v!==adjacency[(k%n)*n+Math.floor(k/n)])) throw new RangeError("Простой граф");
  const a = Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>i===j ? 1 : adjacency[i*n+j]));
  const d = a.map(row=>row.reduce((s,v)=>s+v,0));
  if (features.length !== n || !Number.isInteger(steps) || steps < 0 || steps > 100) throw new RangeError("Features или steps");
  let h = [...features];
  for (let k=0;k<steps;k++) h=a.map((row,i)=>row.reduce((sum,v,j)=>sum+v*h[j]/Math.sqrt(d[i]*d[j]),0));
  return h;
}
','Без ребра нет пути передачи features. Каждая компонента сохраняет собственное состояние. repeat_smoothing(adjacency,features,steps) → S^steps·features. Контракт графа как symmetric_aggregate; steps целое в [0,100]. Каждый шаг синхронный, использует весь прежний вектор. Нет обучаемых W и activation.');
