insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('b1ad9b5f-db54-4fd7-89d6-fd368bd500df','ba9e9e01-6659-4782-8edb-fc50b92940d7','c4350c2022da8dc09d08754d48784d768c8409606e07e59177c90663f005b888','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"repeat_smoothing"}'::jsonb,array['Сначала вычислите новый вектор целиком.','В нерегулярном графе стационарные raw features пропорциональны √degree, не обязательно одинаковы.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn repeat_smoothing(adjacency: &[f64], features: &[f64], steps: f64) -> Result<Vec<f64>, InputError> {
    if adjacency.len() > 256 || adjacency.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if features.len() > 256 || features.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if [steps].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    let n = (adjacency.len() as f64).sqrt() as usize;
    if n == 0 || n*n != adjacency.len() || adjacency.iter().any(|v| *v != 0.0 && *v != 1.0) || (0..n).any(|i|(0..n).any(|j|adjacency[i*n+j] != adjacency[j*n+i])) { return Err(InputError::InvalidInput); }
    let a: Vec<Vec<f64>> = (0..n).map(|i|(0..n).map(|j|if i==j {1.0} else {adjacency[i*n+j]}).collect()).collect();
    let d: Vec<f64> = a.iter().map(|row|row.iter().sum()).collect();
    if features.len()!=n || steps.fract()!=0.0 || !(0.0..=100.0).contains(&steps) { return Err(InputError::InvalidInput); }
    let mut h=features.to_vec();
    for _ in 0..steps as usize {h=(0..n).map(|i|(0..n).map(|j|a[i][j]*h[j]/(d[i]*d[j]).sqrt()).sum()).collect();}
    Ok(h)
}
','Без ребра нет пути передачи features. Каждая компонента сохраняет собственное состояние. repeat_smoothing(adjacency,features,steps) → S^steps·features. Контракт графа как symmetric_aggregate; steps целое в [0,100]. Каждый шаг синхронный, использует весь прежний вектор. Нет обучаемых W и activation.');
