def graphsage_mean_concat(self_feature: float, neighbors: list[float]) -> list[float]:
    if not isinstance(neighbors, (list, tuple)) or len(neighbors) > 256:
        raise ValueError("Некорректный вектор neighbors")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [self_feature, *neighbors]):
        raise ValueError("Некорректные числа")
