insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('5b8b1ac8-6a08-43ba-8389-ea77ba9fc8eb','ba9e9e01-6659-4782-8edb-fc50b92940d7','37741ea98d2fe0618f3a9a46d06d3f16f73795cc8dcb6bf10a2dc4c4827a1926','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"discounted_return"}'::jsonb,array['Первая reward не дисконтируется.','Обход с конца позволяет не возводить gamma в степень.']::text[],'function discounted_return(rewards, gamma) {
  if (!Array.isArray(rewards) || rewards.length > 256) throw new RangeError("Некорректный вектор");
  if ([gamma,...rewards].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректные числа");
  if (gamma < 0 || gamma > 1) throw new RangeError("gamma");
  let value = 0;
  for (let i=rewards.length-1;i>=0;i--) value=rewards[i]+gamma*value;
  return [value];
}
','Третья reward имеет индекс 2: .5²·4=1; полный return=1+1+1=3. discounted_return(rewards,gamma) → [G]. gamma∈[0,1]; пустая траектория разрешена с G=0. Rewards уже получены; переходы MDP и tail bootstrap здесь не моделируются.');
