insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('f7992d20-1c8f-44dd-8a30-dc0f2939623f','ba9e9e01-6659-4782-8edb-fc50b92940d7','c4830a9deb2dd1cdd3e8dcc7f7551fee8fb02fc49f56d043a738a753b82df030','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"discounted_return"}'::jsonb,array['Первая reward не дисконтируется.','Обход с конца позволяет не возводить gamma в степень.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn discounted_return(rewards: &[f64], gamma: f64) -> Result<Vec<f64>, InputError> {
    if rewards.len() > 256 || rewards.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if [gamma].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if !(0.0..=1.0).contains(&gamma) { return Err(InputError::InvalidInput); }
    Ok(vec![rewards.iter().rev().fold(0.0,|v,r|r+gamma*v)])
