insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('59f03bc1-5e59-44ff-8082-a7238009edd8','844d1a36-c6f0-4e21-81e2-2d270325890b','ba9e9e01-6659-4782-8edb-fc50b92940d7','59f03bc1-5e59-44ff-8082-a7238009edd8','unit.rl.bellman.guided',0,'По шагам · Ожидание перед max','Для action0 равновероятны rewards 0 и 2; action1 всегда даёт .5. Bootstrap нулевой. two_action_bellman(probabilities,rewards,next_values,terminal,gamma) → [Q_action0,Q_action1,V_new]. Четыре элемента в каждом векторе: исходы action0, затем action1. P∈[0,1], каждая пара суммируется в 1 (1e−12); terminal — 0/1, gamma∈[0,1]. next_values — один frozen snapshot; это один state backup. Все числовые входы конечны и по модулю ≤10000; векторы содержат не более 256 элементов. Неверный тип или область: ValueError/TypeError в Python, RangeError в JavaScript, InputError в Rust. Вход не изменять. Ответ — новый вектор в указанном порядке; atol=1e−12, rtol=1e−10. Реализуйте функцию для всех допустимых входов; открытый пример не является полным решением.

Q(a)=Σᵢ Pᵢ(rᵢ+γ(1−terminalᵢ)V_old(nextᵢ)); V_new=max_a Q(a)');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('735fdab8-599e-4dfc-8220-ff0c87c375f7','59f03bc1-5e59-44ff-8082-a7238009edd8','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def two_action_bellman(probabilities: list[float], rewards: list[float], next_values: list[float], terminal: list[float], gamma: float) -> list[float]:
    raise NotImplementedError("Реализуйте формулу и проверку входа")
','two_action_bellman','[{"input":{"probabilities":[0.5,0.5,1,0],"rewards":[0,2,0.5,0],"next_values":[0,0,0,0],"terminal":[0,0,0,0],"gamma":0.9},"output":[1,0.5,1]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('735fdab8-599e-4dfc-8220-ff0c87c375f7','ba9e9e01-6659-4782-8edb-fc50b92940d7','3e17620cd961d429b32073ee03019dedaa540ea9c21004496542f2913ff79ab4','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"two_action_bellman"}'::jsonb,array['Сначала взвесьте оба исхода каждого действия.','Terminal outcome не bootstraps даже при ненулевом next_value.']::text[],'import math

def two_action_bellman(probabilities: list[float], rewards: list[float], next_values: list[float], terminal: list[float], gamma: float) -> list[float]:
    if not isinstance(probabilities, (list, tuple)) or len(probabilities) > 256:
        raise ValueError("Некорректный вектор probabilities")
    if not isinstance(rewards, (list, tuple)) or len(rewards) > 256:
        raise ValueError("Некорректный вектор rewards")
    if not isinstance(next_values, (list, tuple)) or len(next_values) > 256:
        raise ValueError("Некорректный вектор next_values")
    if not isinstance(terminal, (list, tuple)) or len(terminal) > 256:
        raise ValueError("Некорректный вектор terminal")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [gamma, *probabilities, *rewards, *next_values, *terminal]):
        raise ValueError("Некорректные числа")
    if any(len(v) != 4 for v in (probabilities,rewards,next_values,terminal)) or not 0 <= gamma <= 1 or any(p < 0 or p > 1 for p in probabilities) or any(t not in (0,1) for t in terminal) or any(abs(sum(probabilities[i:i+2])-1)>1e-12 for i in (0,2)):
        raise ValueError("Два исхода для каждого из двух действий")
    q = [sum(probabilities[j]*(rewards[j]+gamma*next_values[j]*(1-terminal[j])) for j in range(i,i+2)) for i in (0,2)]
    return q+[max(q)]
','Q0=.5·0+.5·2=1; Q1=.5. Value выбирает максимум 1. two_action_bellman(probabilities,rewards,next_values,terminal,gamma) → [Q_action0,Q_action1,V_new]. Четыре элемента в каждом векторе: исходы action0, затем action1. P∈[0,1], каждая пара суммируется в 1 (1e−12); terminal — 0/1, gamma∈[0,1]. next_values — один frozen snapshot; это один state backup.');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('309c23c0-30d2-4b66-82c9-88cfefedca53','59f03bc1-5e59-44ff-8082-a7238009edd8','ba9e9e01-6659-4782-8edb-fc50b92940d7','javascript','function two_action_bellman(probabilities, rewards, next_values, terminal, gamma) {
