pub enum InputError { InvalidInput }
pub fn two_action_bellman(probabilities: &[f64], rewards: &[f64], next_values: &[f64], terminal: &[f64], gamma: f64) -> Result<Vec<f64>, InputError> {
    if probabilities.len() > 256 || probabilities.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if rewards.len() > 256 || rewards.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if next_values.len() > 256 || next_values.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if terminal.len() > 256 || terminal.iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if [gamma].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if [probabilities.len(),rewards.len(),next_values.len(),terminal.len()].iter().any(|n|*n!=4) || !(0.0..=1.0).contains(&gamma) || probabilities.iter().any(|p|*p<0.0||*p>1.0) || terminal.iter().any(|t|*t!=0.0&&*t!=1.0) || [0,2].iter().any(|i|(probabilities[*i]+probabilities[*i+1]-1.0).abs()>1e-12) { return Err(InputError::InvalidInput); }
    let q: Vec<f64>=[0,2].iter().map(|i|(*i..*i+2).map(|j|probabilities[j]*(rewards[j]+gamma*next_values[j]*(1.0-terminal[j]))).sum()).collect();
    Ok(vec![q[0],q[1],q[0].max(q[1])])
}
