insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('9a3610e7-742f-446a-8ad9-bf4947196624','ba9e9e01-6659-4782-8edb-fc50b92940d7','33ed42db466994e72598dc11db724d9c1e2cecc5977ab352ce52365e94db4c89','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"two_action_bellman"}'::jsonb,array['Сначала взвесьте оба исхода каждого действия.','Terminal outcome не bootstraps даже при ненулевом next_value.']::text[],'import math

def two_action_bellman(probabilities: list[float], rewards: list[float], next_values: list[float], terminal: list[float], gamma: float) -> list[float]:
    if not isinstance(probabilities, (list, tuple)) or len(probabilities) > 256:
        raise ValueError("Некорректный вектор probabilities")
    if not isinstance(rewards, (list, tuple)) or len(rewards) > 256:
        raise ValueError("Некорректный вектор rewards")
    if not isinstance(next_values, (list, tuple)) or len(next_values) > 256:
        raise ValueError("Некорректный вектор next_values")
    if not isinstance(terminal, (list, tuple)) or len(terminal) > 256:
        raise ValueError("Некорректный вектор terminal")
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [gamma, *probabilities, *rewards, *next_values, *terminal]):
        raise ValueError("Некорректные числа")
    if any(len(v) != 4 for v in (probabilities,rewards,next_values,terminal)) or not 0 <= gamma <= 1 or any(p < 0 or p > 1 for p in probabilities) or any(t not in (0,1) for t in terminal) or any(abs(sum(probabilities[i:i+2])-1)>1e-12 for i in (0,2)):
        raise ValueError("Два исхода для каждого из двух действий")
    q = [sum(probabilities[j]*(rewards[j]+gamma*next_values[j]*(1-terminal[j])) for j in range(i,i+2)) for i in (0,2)]
    return q+[max(q)]
','Для terminal множитель bootstrap нулевой; остаётся только reward. two_action_bellman(probabilities,rewards,next_values,terminal,gamma) → [Q_action0,Q_action1,V_new]. Четыре элемента в каждом векторе: исходы action0, затем action1. P∈[0,1], каждая пара суммируется в 1 (1e−12); terminal — 0/1, gamma∈[0,1]. next_values — один frozen snapshot; это один state backup.');
