insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('18d54ab0-7d85-4dec-8db3-faebc1fc00b9','ba9e9e01-6659-4782-8edb-fc50b92940d7','93c6e2287573e88dee2283d00be2fc6fc26b259319cd7b3ac233879da75b2262','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"two_action_bellman"}'::jsonb,array['Сначала взвесьте оба исхода каждого действия.','Terminal outcome не bootstraps даже при ненулевом next_value.']::text[],'function two_action_bellman(probabilities, rewards, next_values, terminal, gamma) {
  if (!Array.isArray(probabilities) || probabilities.length > 256) throw new RangeError("Некорректный вектор");
  if (!Array.isArray(rewards) || rewards.length > 256) throw new RangeError("Некорректный вектор");
  if (!Array.isArray(next_values) || next_values.length > 256) throw new RangeError("Некорректный вектор");
  if (!Array.isArray(terminal) || terminal.length > 256) throw new RangeError("Некорректный вектор");
  if ([gamma,...probabilities,...rewards,...next_values,...terminal].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректные числа");
  if ([probabilities,rewards,next_values,terminal].some(v=>v.length!==4) || gamma<0 || gamma>1 || probabilities.some(p=>p<0||p>1) || terminal.some(t=>t!==0&&t!==1) || [0,2].some(i=>Math.abs(probabilities[i]+probabilities[i+1]-1)>1e-12)) throw new RangeError("Два действия, два исхода");
  const q=[0,2].map(i=>[i,i+1].reduce((v,j)=>v+probabilities[j]*(rewards[j]+gamma*next_values[j]*(1-terminal[j])),0));
  return [...q,Math.max(...q)];
}
','Все backups synchronous sweep читают один старый snapshot. Подстановка новых значений меняет алгоритм на асинхронный. two_action_bellman(probabilities,rewards,next_values,terminal,gamma) → [Q_action0,Q_action1,V_new]. Четыре элемента в каждом векторе: исходы action0, затем action1. P∈[0,1], каждая пара суммируется в 1 (1e−12); terminal — 0/1, gamma∈[0,1]. next_values — один frozen snapshot; это один state backup.');
