insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('ae830213-82c0-4d91-8fd8-70e474ef2403','78a2ffbc-01f4-4ac5-83ec-e3c46d322bf0','ba9e9e01-6659-4782-8edb-fc50b92940d7','ae830213-82c0-4d91-8fd8-70e474ef2403','unit.rl.q-learning.guided',0,'По шагам · Обычный переход','Вычислите TD target и новый Q. q_transition_update(old,reward,next_max,gamma,eta,terminated,truncated) → [target,new_Q]. gamma,eta∈[0,1]; flags — числа 0/1. Administrative truncation сохраняет bootstrap; если terminated=1, bootstrap отключается независимо от truncated. Все числовые входы конечны и по модулю ≤10000; векторы содержат не более 256 элементов. Неверный тип или область: ValueError/TypeError в Python, RangeError в JavaScript, InputError в Rust. Вход не изменять. Ответ — новый вектор в указанном порядке; atol=1e−12, rtol=1e−10. Реализуйте функцию для всех допустимых входов; открытый пример не является полным решением.

target=r+γ(1−terminated)max Q_next; Q_new=Q_old+η(target−Q_old)');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('99b719f8-e041-4eda-81e6-a9dceae8dbec','ae830213-82c0-4d91-8fd8-70e474ef2403','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def q_transition_update(old: float, reward: float, next_max: float, gamma: float, eta: float, terminated: float, truncated: float) -> list[float]:
