','q_transition_update','[{"input":{"old":2,"reward":1,"next_max":4,"gamma":0.5,"eta":0.25,"terminated":0,"truncated":0},"output":[3,2.25]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('99b719f8-e041-4eda-81e6-a9dceae8dbec','ba9e9e01-6659-4782-8edb-fc50b92940d7','e9810db2242fd441d44d7d70867afae033dc085685c4f96a4349a18ecc5eae0f','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"q_transition_update"}'::jsonb,array['Не объединяйте terminated и truncated через OR для bootstrap.','next_max должен соответствовать реальному final observation, не observation после auto-reset.']::text[],'import math

def q_transition_update(old: float, reward: float, next_max: float, gamma: float, eta: float, terminated: float, truncated: float) -> list[float]:
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [old, reward, next_max, gamma, eta, terminated, truncated]):
        raise ValueError("Некорректные числа")
    if not 0 <= gamma <= 1 or not 0 <= eta <= 1 or terminated not in (0,1) or truncated not in (0,1):
        raise ValueError("Шаг, discount или флаги")
    target = reward+gamma*next_max*(1-terminated)
    return [target,old+eta*(target-old)]
','Target=1+.5·4=3; error=3−2=1; update=.25. q_transition_update(old,reward,next_max,gamma,eta,terminated,truncated) → [target,new_Q]. gamma,eta∈[0,1]; flags — числа 0/1. Administrative truncation сохраняет bootstrap; если terminated=1, bootstrap отключается независимо от truncated.');
