pub enum InputError { InvalidInput }
pub fn q_transition_update(old: f64, reward: f64, next_max: f64, gamma: f64, eta: f64, terminated: f64, truncated: f64) -> Result<Vec<f64>, InputError> {
    if [old,reward,next_max,gamma,eta,terminated,truncated].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if !(0.0..=1.0).contains(&gamma) || !(0.0..=1.0).contains(&eta) || (terminated!=0.0 && terminated!=1.0) || (truncated!=0.0 && truncated!=1.0) { return Err(InputError::InvalidInput); }
    let target=reward+gamma*next_max*(1.0-terminated);
    Ok(vec![target,old+eta*(target-old)])
}
