insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('20f342a7-78c7-4fe1-8748-d1cb317619b8','ba9e9e01-6659-4782-8edb-fc50b92940d7','a679da851dec41d75dae0e7dd191ee6a6f99537dab564ec2ad332a451ff32bc6','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"q_transition_update"}'::jsonb,array['Не объединяйте terminated и truncated через OR для bootstrap.','next_max должен соответствовать реальному final observation, не observation после auto-reset.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn q_transition_update(old: f64, reward: f64, next_max: f64, gamma: f64, eta: f64, terminated: f64, truncated: f64) -> Result<Vec<f64>, InputError> {
    if [old,reward,next_max,gamma,eta,terminated,truncated].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if !(0.0..=1.0).contains(&gamma) || !(0.0..=1.0).contains(&eta) || (terminated!=0.0 && terminated!=1.0) || (truncated!=0.0 && truncated!=1.0) { return Err(InputError::InvalidInput); }
    let target=reward+gamma*next_max*(1.0-terminated);
    Ok(vec![target,old+eta*(target-old)])
}
','MDP terminal не имеет будущей ценности, target равен reward=1. q_transition_update(old,reward,next_max,gamma,eta,terminated,truncated) → [target,new_Q]. gamma,eta∈[0,1]; flags — числа 0/1. Administrative truncation сохраняет bootstrap; если terminated=1, bootstrap отключается независимо от truncated.');
insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('64db1356-2bfc-4987-85b1-5bf9eafb7e86','78a2ffbc-01f4-4ac5-83ec-e3c46d322bf0','ba9e9e01-6659-4782-8edb-fc50b92940d7','032a5a50-393b-461b-8bb2-b4705ede04ed','unit.rl.q-learning.transfer-b',2,'Перенос B · Лимит времени','Вместо termination отметьте только truncated=1. q_transition_update(old,reward,next_max,gamma,eta,terminated,truncated) → [target,new_Q]. gamma,eta∈[0,1]; flags — числа 0/1. Administrative truncation сохраняет bootstrap; если terminated=1, bootstrap отключается независимо от truncated. Все числовые входы конечны и по модулю ≤10000; векторы содержат не более 256 элементов. Неверный тип или область: ValueError/TypeError в Python, RangeError в JavaScript, InputError в Rust. Вход не изменять. Ответ — новый вектор в указанном порядке; atol=1e−12, rtol=1e−10. Реализуйте функцию для всех допустимых входов; открытый пример не является полным решением.

target=r+γ(1−terminated)max Q_next; Q_new=Q_old+η(target−Q_old)');
