insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('05a74501-b710-4225-81c0-4db8f548e743','ba9e9e01-6659-4782-8edb-fc50b92940d7','9b0ce20fc969b728a585c43480306d74e378fa0caff8d97e7f00ae54ec9a85c9','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"bandit_policy_gradient"}'::jsonb,array['У left derivative log probability равна −p; у right — 1−p.','Общий baseline сохраняет expected gradient, но не обязательно уменьшает variance.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn bandit_policy_gradient(theta: f64, left_reward: f64, right_reward: f64, baseline: f64) -> Result<Vec<f64>, InputError> {
    if [theta,left_reward,right_reward,baseline].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    let p=if theta>=0.0 {1.0/(1.0+(-theta).exp())} else {theta.exp()/(1.0+theta.exp())};
    let left=(left_reward-baseline)*(-p); let right=(right_reward-baseline)*(1.0-p); let expected=(1.0-p)*left+p*right;
    Ok(vec![p,(1.0-p)*left_reward+p*right_reward,p*(1.0-p)*(right_reward-left_reward),expected,(1.0-p)*(left-expected).powi(2)+p*(right-expected).powi(2)])
}
','Right reward выше; dJ=.5. Рост theta увеличивает вероятность right. bandit_policy_gradient(theta,left_reward,right_reward,baseline) → [p_right,J,dJ,E_estimate,Var_estimate]. p_right=sigmoid(theta). Baseline общий для обоих действий, независимый от action; exact enumeration двух исходов, без случайного sampling.');
