insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('4204d2f5-53e7-48e7-82ba-0441383ae354','8e13d07e-d46e-49df-8a2a-91fbfcf61391','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def ppo_clipped_term(ratio: float, advantage: float, epsilon: float) -> list[float]:
    raise NotImplementedError("Реализуйте формулу и проверку входа")
','ppo_clipped_term','[{"input":{"ratio":1.5,"advantage":2,"epsilon":0.2},"output":[2.4]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('4204d2f5-53e7-48e7-82ba-0441383ae354','ba9e9e01-6659-4782-8edb-fc50b92940d7','598de90ba9ec05644c2ed1d5357b19576e194cd4efb830ad54e06ccb80c9a17c','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"ppo_clipped_term"}'::jsonb,array['Сначала умножьте обе ветви на signed advantage, затем min.','При отрицательном A направление ограничения отличается от положительного.']::text[],'import math

def ppo_clipped_term(ratio: float, advantage: float, epsilon: float) -> list[float]:
    if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or abs(v) > 10000 for v in [ratio, advantage, epsilon]):
        raise ValueError("Некорректные числа")
    if ratio <= 0 or not 0 <= epsilon < 1:
        raise ValueError("ratio > 0, epsilon в [0,1)")
    clipped = min(max(ratio,1-epsilon),1+epsilon)
    return [min(ratio*advantage,clipped*advantage)]
','min(3,2.4)=2.4: слишком большое увеличение вероятности ограничивает улучшение surrogate. ppo_clipped_term(ratio,advantage,epsilon) → [objective]. ratio=pi_new(a)/pi_old(a)>0, epsilon∈[0,1). Это член цели для максимизации с уже frozen old policy и advantage; полный PPO/DQN/actor-critic trainer не реализован.');
