insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('410ee748-4578-4110-86d2-75f5b77997e5','ba9e9e01-6659-4782-8edb-fc50b92940d7','d06b10d7d5ca14c7ca39f2d3baae9d6433823cb71a76972cb01a553b8af74d56','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"ppo_clipped_term"}'::jsonb,array['Сначала умножьте обе ветви на signed advantage, затем min.','При отрицательном A направление ограничения отличается от положительного.']::text[],'function ppo_clipped_term(ratio, advantage, epsilon) {
  if ([ratio,advantage,epsilon].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректные числа");
  if (ratio<=0 || epsilon<0 || epsilon>=1) throw new RangeError("ratio или epsilon");
  const clipped=Math.min(Math.max(ratio,1-epsilon),1+epsilon);
  return [Math.min(ratio*advantage,clipped*advantage)];
