insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('8d1c96ff-5870-42ab-8e44-4c8614c8a2f9','ba9e9e01-6659-4782-8edb-fc50b92940d7','42bf6c72a708a7280d7907ec66deb03b39c8e86f2a17eb14c4d6569a78f38edc','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"ppo_clipped_term"}'::jsonb,array['Сначала умножьте обе ветви на signed advantage, затем min.','При отрицательном A направление ограничения отличается от положительного.']::text[],'#[derive(Debug, PartialEq)]
pub enum InputError { InvalidInput }
pub fn ppo_clipped_term(ratio: f64, advantage: f64, epsilon: f64) -> Result<Vec<f64>, InputError> {
    if [ratio,advantage,epsilon].iter().any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }
    if ratio<=0.0 || epsilon<0.0 || epsilon>=1.0 { return Err(InputError::InvalidInput); }
    let clipped=ratio.max(1.0-epsilon).min(1.0+epsilon);
    Ok(vec![(ratio*advantage).min(clipped*advantage)])
}
','min(3,2.4)=2.4: слишком большое увеличение вероятности ограничивает улучшение surrogate. ppo_clipped_term(ratio,advantage,epsilon) → [objective]. ratio=pi_new(a)/pi_old(a)>0, epsilon∈[0,1). Это член цели для максимизации с уже frozen old policy и advantage; полный PPO/DQN/actor-critic trainer не реализован.');
