insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('af7e39d7-15f7-43d0-802a-3209f570e57b','ba9e9e01-6659-4782-8edb-fc50b92940d7','c6e80f57b39287e584a7703863cbfcf969edf17b3c9cb58b3a5ac5df64b07133','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"secant_quadratic"}'::jsonb,array['Знаменатель — изменение входа h, а не исходный x.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn secant_quadratic(x: f64, h: f64) -> Result<f64, InputError> {
    if !x.is_finite()||x.abs()>100.0||!h.is_finite()||!(1e-6..=1.0).contains(&h.abs()){return Err(InputError::InvalidInput);}
    Ok(((x+h).powi(2)-x*x)/h)
}
