pub enum InputError { InvalidInput }
pub fn quadratic_prediction(x: f64, delta: f64) -> Result<Vec<f64>, InputError> {
    if !x.is_finite()||x.abs()>100.0||!delta.is_finite()||delta.abs()>1.0{return Err(InputError::InvalidInput);}
    Ok(vec![2.0*x,2.0*x*delta,(x+delta).powi(2)-x*x])
}
