insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('7ea08a19-95a4-46be-86fc-5a5f9b50fe61','ba9e9e01-6659-4782-8edb-fc50b92940d7','b10245bb8d68112bfd0c4fd1df64147a8a2737698642c131b5eeb77e962f7728','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"coordinate_difference"}'::jsonb,array['Создайте отдельные копии точки для плюс и минус.']::text[],'import math

def coordinate_difference(point: list[float], axis: int, h: float) -> float:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if len(point)!=2 or any(not finite(a) or abs(a)>100 for a in point) or type(axis) is not int or axis not in (0,1) or not finite(h) or not 1e-6<=h<=1: raise ValueError("Некорректная координата или шаг")
    def loss(p): return (p[0]**2+8*p[1]**2)/2
    plus=point.copy();minus=point.copy();plus[axis]+=h;minus[axis]-=h
    return (loss(plus)-loss(minus))/(2*h)
','Для [2,1],axis=0,h=.125 производная по x равна 2.');
