  if(!Array.isArray(point)||point.length!==2||point.some(a=>!Number.isFinite(a)||Math.abs(a)>100)||!Number.isInteger(axis)||axis<0||axis>1||!Number.isFinite(h)||h<1e-6||h>1)throw new RangeError("Некорректная координата или шаг");
  const loss=p=>(p[0]**2+8*p[1]**2)/2,plus=[...point],minus=[...point];plus[axis]+=h;minus[axis]-=h;return (loss(plus)-loss(minus))/(2*h);
