insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('aa6c028b-57a3-43e1-8b2f-59cd11603a04','ba9e9e01-6659-4782-8edb-fc50b92940d7','fc5b1acac1ef4e498f48e084441a0cdb14c3e6b3ce6a588e9e68a1ed873a8210','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"coordinate_difference"}'::jsonb,array['Создайте отдельные копии точки для плюс и минус.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn coordinate_difference(point: &[f64], axis: usize, h: f64) -> Result<f64, InputError> {
    if point.len()!=2||point.iter().any(|a|!a.is_finite()||a.abs()>100.0)||axis>1||!h.is_finite()||!(1e-6..=1.0).contains(&h){return Err(InputError::InvalidInput);}
    let loss=|p:&[f64]|(p[0].powi(2)+8.0*p[1].powi(2))/2.0;let mut plus=point.to_vec();let mut minus=point.to_vec();plus[axis]+=h;minus[axis]-=h;Ok((loss(&plus)-loss(&minus))/(2.0*h))
}
','Для [2,1],axis=0,h=.125 производная по x равна 2.');
