insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('d376a31b-34bf-49de-8df7-9173d027a6d8','ba9e9e01-6659-4782-8edb-fc50b92940d7','0f8be664c0dadb1999b3e70f4694dd7b65b4099ddc283071f050af8d5415b317','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"quadratic_gradient"}'::jsonb,array['Отделяйте свойство данной потери от общего утверждения.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn quadratic_gradient(point: &[f64], direction: &[f64]) -> Result<Vec<f64>, InputError> {
    if point.len()!=2||direction.len()!=2||point.iter().chain(direction).any(|a|!a.is_finite()||a.abs()>100.0)||(direction.iter().map(|a|a*a).sum::<f64>()-1.0).abs()>1e-10{return Err(InputError::InvalidInput);}
    let(gx,gy)=(point[0],8.0*point[1]);Ok(vec![gx,gy,gx*direction[0]+gy*direction[1]])
}
','Ответ [0,0,0]. Само равенство градиента нулю не доказывает минимум.');
