    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if any(not finite(v) or abs(v)>100 for v in (x,a,b,c)): raise ValueError("Некорректные параметры композиции")
    u=a*x+b
    return 2*u*a+c
