def matmul(a: list[list[float]], b: list[list[float]]) -> list[list[float]]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not a or not b or not a[0] or not b[0] or max(len(a),len(b),len(a[0]),len(b[0]))>16 or len(a[0])!=len(b): raise ValueError("Несовместимые размеры матриц")
