pub enum InputError { InvalidInput }
pub fn flat_index(shape: &[usize], indices: &[usize]) -> Result<Vec<f64>, InputError> {
    if shape.len()>4||shape.len()!=indices.len()||shape.iter().any(|s|*s==0||*s>64)||indices.iter().zip(shape).any(|(i,s)|i>=s){return Err(InputError::InvalidInput);}
