def expectation(p: list[float], values: list[float]) -> float:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(p)<=64 or len(p)!=len(values) or any(not finite(a) or not 0<=a<=1 for a in p) or abs(sum(p)-1)>1e-10 or any(not finite(v) or abs(v)>10000 for v in values): raise ValueError("Неверные вероятности или значения")
    mean=sum(a*v for a,v in zip(p,values))
    return mean
