insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('4937770b-9566-423a-84cf-066e98fb7316','ba9e9e01-6659-4782-8edb-fc50b92940d7','4033851c1d42541574a230c93a7e74850117685e117c078164f24fc3a10f751a','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"weighted_variance"}'::jsonb,array['Возводите отклонение в квадрат до суммирования.']::text[],'import math

def weighted_variance(p: list[float], values: list[float]) -> float:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(p)<=64 or len(p)!=len(values) or any(not finite(a) or not 0<=a<=1 for a in p) or abs(sum(p)-1)>1e-10 or any(not finite(v) or abs(v)>10000 for v in values): raise ValueError("Неверные вероятности или значения")
    mean=sum(a*v for a,v in zip(p,values))
    return sum(a*(v-mean)**2 for a,v in zip(p,values))
','Для [.25,.75] и [0,4] среднее 3, дисперсия .25·9+.75·1=3.');
