insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('7a152e55-2f88-4277-84eb-9e3198054a42','ba9e9e01-6659-4782-8edb-fc50b92940d7','c80f247361f6956976ffb438c815338801cb52d682b115692509f15be2f25547','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"weighted_variance"}'::jsonb,array['Возводите отклонение в квадрат до суммирования.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn weighted_variance(p: &[f64], values: &[f64]) -> Result<f64, InputError> {
    if p.is_empty()||p.len()>64||p.len()!=values.len()||p.iter().any(|a|!a.is_finite()||!(0.0..=1.0).contains(a))||(p.iter().sum::<f64>()-1.0).abs()>1e-10||values.iter().any(|v|!v.is_finite()||v.abs()>10000.0){return Err(InputError::InvalidInput);}
    let mean=p.iter().zip(values).map(|(a,v)|a*v).sum::<f64>();Ok(p.iter().zip(values).map(|(a,v)|a*(v-mean).powi(2)).sum())
