pub enum InputError { InvalidInput }
pub fn shifted_exp(values: &[f64]) -> Result<Vec<f64>, InputError> {
    if values.is_empty()||values.len()>64||values.iter().any(|v|!v.is_finite()||v.abs()>10000.0){return Err(InputError::InvalidInput);}
