pub fn negative_log_probability(probabilities: &[f64]) -> Result<f64, InputError> {
    if probabilities.is_empty()||probabilities.len()>64||probabilities.iter().any(|p|!p.is_finite()||*p<=0.0||*p>1.0){return Err(InputError::InvalidInput);}
    Ok(-probabilities.iter().map(|p|p.ln()).sum::<f64>())
