insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('b264d751-d985-48da-83bd-16a1b00f06a3','ba9e9e01-6659-4782-8edb-fc50b92940d7','c558c2487b2d7fb44b4e93bed018d713ed6c6c6db0dd9c083eacfcbe302cb548','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"entropy"}'::jsonb,array['Суммируются те же два взвешенных логарифма.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn entropy(p: &[f64]) -> Result<f64, InputError> {
    if p.is_empty()||p.len()>64||p.iter().any(|a|!a.is_finite()||!(0.0..=1.0).contains(a))||(p.iter().sum::<f64>()-1.0).abs()>1e-10{return Err(InputError::InvalidInput);}
    Ok(-p.iter().filter(|a|**a>0.0).map(|a|a*a.ln()).sum::<f64>())
}
