insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('854543de-5e2c-4b54-8951-5c31f1fe1669','fbe652ec-0f5a-41fb-8e82-df1c50814ff4','ba9e9e01-6659-4782-8edb-fc50b92940d7','854543de-5e2c-4b54-8951-5c31f1fe1669','concept.softmax.guided',0,'Вероятности из логитов','Напишите softmax(z,temperature) с вычитанием максимума. Этот математический примитив затем используется в разных задачах уроков. Векторы непустые, нужные длины совпадают, максимум 64 элемента. Числа конечны в ±10000; вход не менять. Неверные значения отклоняются: ValueError/RangeError/InputError. atol=1e−12,rtol=1e−10. Температура конечна в [.1,10]. Машинное округление малой вероятности к нулю допустимо.

