insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('9813a96f-cfcd-4c36-8a4b-6a7355ee4ae0','ba9e9e01-6659-4782-8edb-fc50b92940d7','8ddde3a1953ef0e505b679b954c36c595b5c31c4bfcad2e95570801b6621a644','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"softmax"}'::jsonb,array['Высокая температура сближает вероятности.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn softmax(z: &[f64], temperature: f64) -> Result<Vec<f64>, InputError> {
    if z.is_empty()||z.len()>64||z.iter().any(|a|!a.is_finite()||a.abs()>10000.0)||!temperature.is_finite()||!(0.1..=10.0).contains(&temperature){return Err(InputError::InvalidInput);}
    let m=z.iter().copied().fold(f64::NEG_INFINITY,f64::max);let e:Vec<f64>=z.iter().map(|a|((a-m)/temperature).exp()).collect();let total:f64=e.iter().sum();Ok(e.iter().map(|a|a/total).collect())
}
','Ответ [1/(1+√3),√3/(1+√3)] ближе к равномерному, чем [.25,.75].');
