insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('0d494386-9810-4c50-82db-c6b79762aa49','e67682fc-f188-43bd-8fdc-146f467abf51','ba9e9e01-6659-4782-8edb-fc50b92940d7','0d494386-9810-4c50-82db-c6b79762aa49','concept.normalization.guided',0,'Центрировать и нормировать признаки','Напишите layer_norm(x,gamma,beta,eps). Вычислите среднее и дисперсию одного вектора, затем примените масштаб и сдвиг по каждому признаку. Векторы непустые, нужные длины совпадают, максимум 64 элемента. Числа конечны в ±10000; вход не менять. Неверные значения отклоняются: ValueError/RangeError/InputError. atol=1e−12,rtol=1e−10. Здесь значения x, gamma, beta в ±1000; их длины совпадают. eps∈[1e−12,1]. Делитель дисперсии — n. Нормализация идёт по признакам одного примера, не по всему пакету.

μ=Σx/n; σ²=Σ(x−μ)²/n; yᵢ=γᵢ(xᵢ−μ)/√(σ²+ε)+βᵢ');
