def layer_norm(x: list[float], gamma: list[float], beta: list[float], eps: float) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    raise NotImplementedError("Реализуйте правило")
','layer_norm','[{"input":{"x":[1,3],"gamma":[1,1],"beta":[0,0],"eps":1},"output":[-0.7071067811865475,0.7071067811865475]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('2ce1b140-f6d5-4b70-8a8a-e84fe81fbf68','ba9e9e01-6659-4782-8edb-fc50b92940d7','f93996d68844b2d9654ca88b23a7c1cec55d3d82e8be97e2b1f72d693ea07e37','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"layer_norm"}'::jsonb,array['Добавляйте eps к дисперсии внутри квадратного корня.']::text[],'import math

def layer_norm(x: list[float], gamma: list[float], beta: list[float], eps: float) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(x)<=64 or len(x)!=len(gamma) or len(x)!=len(beta) or any(not finite(v) or abs(v)>1000 for v in x+gamma+beta) or not finite(eps) or not 1e-12<=eps<=1: raise ValueError("Неверные параметры нормализации")
    mean=sum(x)/len(x);variance=sum((v-mean)**2 for v in x)/len(x)
    return [g*(v-mean)/math.sqrt(variance+eps)+b for v,g,b in zip(x,gamma,beta)]
','У [1,3] среднее 2, дисперсия 1. При eps=1 нормированные значения равны ±1/√2.');
