    if x.is_empty()||x.len()>64||x.len()!=gamma.len()||x.len()!=beta.len()||x.iter().chain(gamma).chain(beta).any(|v|!v.is_finite()||v.abs()>1000.0)||!eps.is_finite()||!(1e-12..=1.0).contains(&eps){return Err(InputError::InvalidInput);}
