insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('d62d2623-e543-4101-8364-777e57288213','ba9e9e01-6659-4782-8edb-fc50b92940d7','343a2e0881eb6272d40a4da272868810dd3f601a1d26f01795d71455385f46d8','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"layer_norm"}'::jsonb,array['После вычитания среднего числители равны нулю.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn layer_norm(x: &[f64], gamma: &[f64], beta: &[f64], eps: f64) -> Result<Vec<f64>, InputError> {
    if x.is_empty()||x.len()>64||x.len()!=gamma.len()||x.len()!=beta.len()||x.iter().chain(gamma).chain(beta).any(|v|!v.is_finite()||v.abs()>1000.0)||!eps.is_finite()||!(1e-12..=1.0).contains(&eps){return Err(InputError::InvalidInput);}
    let mean=x.iter().sum::<f64>()/x.len() as f64;let variance=x.iter().map(|v|(v-mean).powi(2)).sum::<f64>()/x.len() as f64;Ok(x.iter().zip(gamma).zip(beta).map(|((v,g),b)|g*(v-mean)/(variance+eps).sqrt()+b).collect())
}
','Выход совпадает с beta. Положительный eps делает вычисление определённым при нулевой дисперсии.');
