insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('7693c55b-ea05-4efe-8a84-95964f4227f2','ba9e9e01-6659-4782-8edb-fc50b92940d7','8fb98c34d2eba78ae21118a4d05b06579809a4bec194ec37310df5535c17aa97','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"mean_squared_error"}'::jsonb,array['Сумма ошибок может сократиться, сумма их квадратов — нет.']::text[],'import math

def mean_squared_error(predictions: list[float], targets: list[float]) -> float:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(predictions)<=64 or len(predictions)!=len(targets) or any(not finite(v) or abs(v)>1000 for v in predictions+targets): raise ValueError("Несовместимые предсказания и цели")
    return sum((p-y)**2 for p,y in zip(predictions,targets))/len(predictions)
','Для ошибок [1,−1] средняя ошибка 0, но MSE=1. Знаки не устраняют штраф.');
