insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('8a1cd8a8-af96-4acf-899f-9c67be4d7d97','ba9e9e01-6659-4782-8edb-fc50b92940d7','2d916ffdf4a380df71b653b5138f0aea954f3f71865f816863b0a36f3e868213','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"mean_squared_error"}'::jsonb,array['Не используйте делитель из предыдущей задачи.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn mean_squared_error(predictions: &[f64], targets: &[f64]) -> Result<f64, InputError> {
    if predictions.is_empty()||predictions.len()>64||predictions.len()!=targets.len()||predictions.iter().chain(targets).any(|v|!v.is_finite()||v.abs()>1000.0){return Err(InputError::InvalidInput);}
    Ok(predictions.iter().zip(targets).map(|(p,y)|(p-y).powi(2)).sum::<f64>()/predictions.len() as f64)
}
','MSE=12/4=3. Повторение всей выборки не меняет её среднюю потерю.');
