insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('64833de9-5124-4af2-80b8-d2cfc68a5dbb','ba9e9e01-6659-4782-8edb-fc50b92940d7','ff8a2016a79a8d206499e9b2f85d74aeeb3bb0454bccccabaeab494c3a8687d3','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"logit_cross_entropy"}'::jsonb,array['Вычисляйте разность m−z[target] до сложения с логарифмом.']::text[],'import math

def logit_cross_entropy(z: list[float], target: int) -> float:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 2<=len(z)<=64 or any(not finite(v) or abs(v)>10000 for v in z) or type(target) is not int or not 0<=target<len(z): raise ValueError("Неверные логиты или индекс класса")
    m=max(z)
    return math.log(sum(math.exp(v-m) for v in z))+(m-z[target])
