insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('9b74f2dd-3f87-4ed5-8647-24752e1200c8','ba9e9e01-6659-4782-8edb-fc50b92940d7','53399cd39071f8fda47a1185ed145f72dac320e0a8522e79dc7e7d559e5cfa5f','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"logit_cross_entropy"}'::jsonb,array['Вычисляйте разность m−z[target] до сложения с логарифмом.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn logit_cross_entropy(z: &[f64], target: usize) -> Result<f64, InputError> {
    if z.len()<2||z.len()>64||z.iter().any(|v|!v.is_finite()||v.abs()>10000.0)||target>=z.len(){return Err(InputError::InvalidInput);}
    let m=z.iter().copied().fold(f64::NEG_INFINITY,f64::max);Ok(z.iter().map(|v|(v-m).exp()).sum::<f64>().ln()+(m-z[target]))
}
','При [0,ln3] и классе 1 вероятность верного класса .75, поэтому потеря ln(4/3).');
