insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('f61adb29-ac1d-40e9-8bf8-77a01e221c02','06157ee9-0e19-41f5-817b-08f8ac055f0d','ba9e9e01-6659-4782-8edb-fc50b92940d7','f61adb29-ac1d-40e9-8bf8-77a01e221c02','concept.backpropagation.guided',0,'Сложить локальные вклады','Напишите backprop_graph(x,w,target). Сохраните q и p в прямом проходе; в обратном сложите вклад квадрата и линейной ветви. x, w и target конечны в ±4. Верните [q,p,L,dL/dx,dL/dw]. Градиент узла q получает вклады обоих путей: q² и q. Входные значения не менять.

q=wx; p=q²+q; L=(p−y)²/2; dL/dq=(p−y)(2q+1)');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('0134d989-0b93-4311-8be7-ec3445acc097','f61adb29-ac1d-40e9-8bf8-77a01e221c02','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def backprop_graph(x: float, w: float, target: float) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    raise NotImplementedError("Реализуйте правило")
','backprop_graph','[{"input":{"x":2,"w":0.5,"target":1},"output":[1,2,0.5,1.5,6]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('0134d989-0b93-4311-8be7-ec3445acc097','ba9e9e01-6659-4782-8edb-fc50b92940d7','630cf34f5ae63202a5f1ecacf304a63fdba18d58eb4d3397898255ae704fd13e','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"backprop_graph"}'::jsonb,array['Для q² локальная производная 2q, для q — 1.']::text[],'import math

def backprop_graph(x: float, w: float, target: float) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if any(not finite(v) or abs(v)>4 for v in (x,w,target)): raise ValueError("Неверные параметры графа")
    q=w*x;p=q*q+q;error=p-target
    dq=error*(2*q+1)
    return [q,p,error*error/2,dq*w,dq*x]
