insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('87f6c001-232c-4f08-8e4e-dec09e622179','ba9e9e01-6659-4782-8edb-fc50b92940d7','66d615105c377030bd791f6beac8ec2aef57c5edbf18b5e48d6ae814eaea3441','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"fit_standardizer"}'::jsonb,array['Выборка, по которой оцениваются параметры, должна быть явно обучающей.']::text[],'import math

def fit_standardizer(train: list[float]) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(train)<=64 or any(not finite(v) or abs(v)>1000 for v in train): raise ValueError("Неверная обучающая выборка")
    mean=sum(train)/len(train);variance=sum((v-mean)**2 for v in train)/len(train)
    return [mean,math.sqrt(variance) if variance>0 else 1]
','Среднее 1, масштаб 1. Значения validation и test не должны входить в эти суммы.');
