pub enum InputError { InvalidInput }
pub fn fit_standardizer(train: &[f64]) -> Result<Vec<f64>, InputError> {
    if train.is_empty()||train.len()>64||train.iter().any(|v|!v.is_finite()||v.abs()>1000.0){return Err(InputError::InvalidInput);}
    let mean=train.iter().sum::<f64>()/train.len() as f64;let variance=train.iter().map(|v|(v-mean).powi(2)).sum::<f64>()/train.len() as f64;Ok(vec![mean,if variance>0.0{variance.sqrt()}else{1.0}])
}
','Среднее 1, масштаб 1. Значения validation и test не должны входить в эти суммы.');
