insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('8caced5a-a606-45c6-81fd-551f8fe47420','ba9e9e01-6659-4782-8edb-fc50b92940d7','8e44871bd2a445b2ca08dba4623a333dab04b8f52f907b0debf907001e6eea9e','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"fit_standardizer"}'::jsonb,array['Нулевая дисперсия не должна приводить к делению на ноль.']::text[],'import math

def fit_standardizer(train: list[float]) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(train)<=64 or any(not finite(v) or abs(v)>1000 for v in train): raise ValueError("Неверная обучающая выборка")
    mean=sum(train)/len(train);variance=sum((v-mean)**2 for v in train)/len(train)
    return [mean,math.sqrt(variance) if variance>0 else 1]
','Параметры [7,1]. Это оговорка для постоянного признака, не разрешение выбирать настройки по test.');
