def generalization_gap(train_losses: list[float], heldout_losses: list[float]) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(train_losses)<=64 or not 1<=len(heldout_losses)<=64 or any(not finite(v) or not 0<=v<=10000 for v in train_losses+heldout_losses): raise ValueError("Неверные списки потерь")
    a=sum(train_losses)/len(train_losses);b=sum(heldout_losses)/len(heldout_losses)
    return [a,b,b-a]
