pub enum InputError { InvalidInput }
pub fn generalization_gap(train_losses: &[f64], heldout_losses: &[f64]) -> Result<Vec<f64>, InputError> {
    if train_losses.is_empty()||heldout_losses.is_empty()||train_losses.len()>64||heldout_losses.len()>64||train_losses.iter().chain(heldout_losses).any(|v|!v.is_finite()||!(0.0..=10000.0).contains(v)){return Err(InputError::InvalidInput);}
    let a=train_losses.iter().sum::<f64>()/train_losses.len() as f64;let b=heldout_losses.iter().sum::<f64>()/heldout_losses.len() as f64;Ok(vec![a,b,b-a])
