insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('09ec70ba-cdec-43cc-8229-575a99a41d42','ba9e9e01-6659-4782-8edb-fc50b92940d7','be34cbb2bbb1a4e58e62ceaed4e65d1de29f0208baede3bd2552e8e533197dfb','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"l2_penalty_and_grad"}'::jsonb,array['Множитель 1/2 сокращается при дифференцировании квадрата.']::text[],'import math

def l2_penalty_and_grad(weights: list[float], strength: float) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(weights)<=64 or any(not finite(v) or abs(v)>100 for v in weights) or not finite(strength) or not 0<=strength<=1: raise ValueError("Неверные параметры штрафа")
    return [strength*sum(v*v for v in weights)/2]+[strength*v for v in weights]
','Для [2,−1], lambda=.2 штраф .5, градиент [.4,−.2]. Производная направлена от нуля; шаг вычитает её.');
