insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('0991782f-ca32-46dc-8836-88ef7e10ec92','ba9e9e01-6659-4782-8edb-fc50b92940d7','78b3c5ebbd550b794d4b45ca4109c38d0c5f554c63198a936ee13af2d9f88a16','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"l2_penalty_and_grad"}'::jsonb,array['Множитель 1/2 сокращается при дифференцировании квадрата.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn l2_penalty_and_grad(weights: &[f64], strength: f64) -> Result<Vec<f64>, InputError> {
    if weights.is_empty()||weights.len()>64||weights.iter().any(|v|!v.is_finite()||v.abs()>100.0)||!strength.is_finite()||!(0.0..=1.0).contains(&strength){return Err(InputError::InvalidInput);}
    let mut out=vec![strength*weights.iter().map(|v|v*v).sum::<f64>()/2.0];out.extend(weights.iter().map(|v|strength*v));Ok(out)
