insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('0397d818-2ba3-4602-8a04-1fe7d02427d8','cfb31965-565c-46e6-87c6-482ef0984681','ba9e9e01-6659-4782-8edb-fc50b92940d7','0397d818-2ba3-4602-8a04-1fe7d02427d8','concept.initialization.guided',0,'Выбрать стандартное отклонение для ReLU','Напишите fan_in_scale(fan_in,fan_out,kind). Для kind=he используйте число входов слоя, затем возьмите квадратный корень дисперсии. fan_in и fan_out — целые от 1 до 1000000; kind равен he или xavier. Верните [дисперсия, стандартное отклонение]. Это выбор масштаба, без генератора случайных чисел и без гарантии успешного обучения; нулевой bias допустим.

VarHe=2/fan_in; VarXavier=2/(fan_in+fan_out); std=√Var');
