insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('ab0c6233-7271-45da-8193-ade0bc216e8e','ba9e9e01-6659-4782-8edb-fc50b92940d7','f998634b407486371241e8d81ae818a6cb07c8d38020eda1126d276f78d107a5','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"fan_in_scale"}'::jsonb,array['Не путайте дисперсию и стандартное отклонение.']::text[],'import math

def fan_in_scale(fan_in: int, fan_out: int, kind: str) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if type(fan_in) is not int or type(fan_out) is not int or not 1<=fan_in<=1000000 or not 1<=fan_out<=1000000 or kind not in ("he","xavier"): raise ValueError("Неверные параметры инициализации")
    variance=2/fan_in if kind=="he" else 2/(fan_in+fan_out)
    return [variance,math.sqrt(variance)]
','При fan_in=8 дисперсия .25, стандартное отклонение .5. Число выходов не входит в данную формулу He.');
