insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('b8393e2e-209e-4a98-80b7-5df006bb52d9','ba9e9e01-6659-4782-8edb-fc50b92940d7','822d73d77cc88a8ebe5823c619589a252cf4032c08924f1af2fdea6e935318c8','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"fan_in_scale"}'::jsonb,array['Не путайте дисперсию и стандартное отклонение.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn fan_in_scale(fan_in: usize, fan_out: usize, kind: &str) -> Result<Vec<f64>, InputError> {
    if fan_in==0||fan_out==0||fan_in>1000000||fan_out>1000000{return Err(InputError::InvalidInput);}
    let variance=match kind{"he"=>2.0/fan_in as f64,"xavier"=>2.0/(fan_in+fan_out) as f64,_=>return Err(InputError::InvalidInput)};Ok(vec![variance,variance.sqrt()])
}
