insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('b006f38e-356a-4602-880d-62dd653d9987','ba9e9e01-6659-4782-8edb-fc50b92940d7','8618ad3d14d741c14680b43ca6a9abace8b220ea8ea0bf31c1b0d5a186022803','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"batch_indices"}'::jsonb,array['Последний конец пакета ограничивается n.']::text[],'import math

def batch_indices(n: int, batch_size: int) -> list[list[float]]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if type(n) is not int or type(batch_size) is not int or not 1<=n<=10000 or not 1<=batch_size<=10000: raise ValueError("Неверные размеры пакетов")
    return [list(range(start,min(start+batch_size,n))) for start in range(0,n,batch_size)]
','При N=5,B=2 получаются [0,1],[2,3],[4]: три шага с неполным последним пакетом.');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('371f5d98-c1d2-4759-88a8-7c4742023c51','4f102181-87e5-4a77-89fc-588b8bba5078','ba9e9e01-6659-4782-8edb-fc50b92940d7','javascript','function batchIndices(n, batch_size) {
