insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('371f5d98-c1d2-4759-88a8-7c4742023c51','ba9e9e01-6659-4782-8edb-fc50b92940d7','fd662c8952adce79ab2af05614db97dfee8403d803cb458e50d1344458feb709','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"batchIndices"}'::jsonb,array['Последний конец пакета ограничивается n.']::text[],'function batchIndices(n, batch_size) {
  if(!Number.isInteger(n)||!Number.isInteger(batch_size)||n<1||n>10000||batch_size<1||batch_size>10000)throw new RangeError("Неверные размеры пакетов");const out=[];for(let start=0;start<n;start+=batch_size){const row=[];for(let i=start;i<Math.min(start+batch_size,n);i++)row.push(i);out.push(row);}return out;
}
','При N=5,B=2 получаются [0,1],[2,3],[4]: три шага с неполным последним пакетом.');
