insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('0ca6449d-15c3-4837-8d02-5116ab0a9d77','ba9e9e01-6659-4782-8edb-fc50b92940d7','c96feb8031fce45066da5a3265ad33a12b9b4d3b36dd38ac01d2201b7686eac0','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"batch_indices"}'::jsonb,array['Последний конец пакета ограничивается n.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn batch_indices(n: usize, batch_size: usize) -> Result<Vec<Vec<f64>>, InputError> {
    if n==0||n>10000||batch_size==0||batch_size>10000{return Err(InputError::InvalidInput);}
    Ok((0..n).step_by(batch_size).map(|start|(start..(start+batch_size).min(n)).map(|i|i as f64).collect()).collect())
}
','При N=5,B=2 получаются [0,1],[2,3],[4]: три шага с неполным последним пакетом.');
