def weighted_epoch_loss(means: list[float], counts: list[int]) -> float:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(means)<=64 or len(means)!=len(counts) or any(not finite(v) or not 0<=v<=10000 for v in means) or any(type(n) is not int or not 1<=n<=10000 for n in counts): raise ValueError("Неверные средние или размеры пакетов")
    return sum(m*n for m,n in zip(means,counts))/sum(counts)
