insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('9ede3d2c-2848-4679-8c6d-29c5d3a1d2a4','ba9e9e01-6659-4782-8edb-fc50b92940d7','6e7b64e1f04eba2c410a370b89e2fd025832614fc9bddc6c92ffedc75445fbf5','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"weighted_epoch_loss"}'::jsonb,array['Вес среднего пакета равен его фактическому числу примеров.']::text[],'#[derive(Debug)]
pub enum InputError { InvalidInput }
pub fn weighted_epoch_loss(means: &[f64], counts: &[usize]) -> Result<f64, InputError> {
    if means.is_empty()||means.len()>64||means.len()!=counts.len()||means.iter().any(|v|!v.is_finite()||!(0.0..=10000.0).contains(v))||counts.iter().any(|n|*n==0||*n>10000){return Err(InputError::InvalidInput);}
    Ok(means.iter().zip(counts).map(|(m,n)|m*(*n as f64)).sum::<f64>()/counts.iter().sum::<usize>() as f64)
}
','Ответ 13/5=2.6. Простое среднее трёх средних 11/3 неверно: хвост получил бы лишний вес.');
