insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('5620dccd-0111-44eb-8dfa-3775132aa293','ba9e9e01-6659-4782-8edb-fc50b92940d7','ae31953d77bc150223ae10d578d74c6599c1a035115cbebdfe2197e54ca76b9f','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"adamw_decay_step"}'::jsonb,array['Оба слагаемых используют старое значение theta.']::text[],'import math

def adamw_decay_step(theta: list[float], adaptive: list[float], eta: float, strength: float) -> list[float]:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(theta)<=64 or len(theta)!=len(adaptive) or any(not finite(v) or abs(v)>100 for v in theta+adaptive) or any(not finite(v) or not 0<=v<=1 for v in (eta,strength)): raise ValueError("Неверные параметры AdamW")
    return [w*(1-eta*strength)-eta*u for w,u in zip(theta,adaptive)]
