pub enum InputError { InvalidInput }
pub fn adamw_decay_step(theta: &[f64], adaptive: &[f64], eta: f64, strength: f64) -> Result<Vec<f64>, InputError> {
    if theta.is_empty()||theta.len()>64||theta.len()!=adaptive.len()||theta.iter().chain(adaptive).any(|v|!v.is_finite()||v.abs()>100.0)||[eta,strength].iter().any(|v|!v.is_finite()||!(0.0..=1.0).contains(v)){return Err(InputError::InvalidInput);}
