insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('768b27d4-47fd-4793-8dec-aac3321e7204','ba9e9e01-6659-4782-8edb-fc50b92940d7','e67c26d7b93578929b50f1c5492b60379fc05b344bd233a17396ab8a8d66e13a','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"classification_metrics"}'::jsonb,array['Равенство порогу считается положительным решением.']::text[],'import math

def classification_metrics(p: list[float], labels: list[float], threshold: float) -> dict:
    finite = lambda x: type(x) in (int,float) and math.isfinite(x)
    if not 1<=len(p)<=64 or len(p)!=len(labels) or any(not finite(v) or not 0<=v<=1 for v in p) or any(not finite(y) or y not in (0,1) for y in labels) or not finite(threshold) or not 0<=threshold<=1: raise ValueError("Неверные данные метрик")
    tp=fp=fn=tn=0
    for v,y in zip(p,labels):
        if v>=threshold:
            if y==1: tp+=1
            else: fp+=1
        else:
            if y==1: fn+=1
            else: tn+=1
    return {"accuracy":(tp+tn)/len(p),"precisionDefined":tp+fp>0,"precision":tp/(tp+fp) if tp+fp>0 else 0,"recallDefined":tp+fn>0,"recall":tp/(tp+fn) if tp+fn>0 else 0,"counts":[tp,fp,fn,tn]}
','Для [.8,.6,.2,.1] и [1,0,1,0] все четыре счётчика равны 1; accuracy, precision и recall равны .5.');
