pub enum InputError { InvalidInput }
#[allow(non_snake_case)]
pub struct Metrics { pub accuracy:f64,pub precisionDefined:bool,pub precision:f64,pub recallDefined:bool,pub recall:f64,pub counts:Vec<f64> }
pub fn classification_metrics(p: &[f64], labels: &[f64], threshold: f64) -> Result<Metrics, InputError> {
    if p.is_empty()||p.len()>64||p.len()!=labels.len()||p.iter().any(|v|!v.is_finite()||!(0.0..=1.0).contains(v))||labels.iter().any(|y|!y.is_finite()||(*y!=0.0&&*y!=1.0))||!threshold.is_finite()||!(0.0..=1.0).contains(&threshold){return Err(InputError::InvalidInput);}
    let(mut tp,mut fp,mut miss,mut tn)=(0.0,0.0,0.0,0.0);for(v,y)in p.iter().zip(labels){if *v>=threshold{if *y==1.0{tp+=1.0;}else{fp+=1.0;}}else if *y==1.0{miss+=1.0;}else{tn+=1.0;}}Ok(Metrics{accuracy:(tp+tn)/p.len() as f64,precisionDefined:tp+fp>0.0,precision:if tp+fp>0.0{tp/(tp+fp)}else{0.0},recallDefined:tp+miss>0.0,recall:if tp+miss>0.0{tp/(tp+miss)}else{0.0},counts:vec![tp,fp,miss,tn]})
}
','Для [.8,.6,.2,.1] и [1,0,1,0] все четыре счётчика равны 1; accuracy, precision и recall равны .5.');
