insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('449d110c-a311-43fe-8d20-0e23a68c5eb6','70caba61-d01d-4d2c-823e-165f4a3ce672','ba9e9e01-6659-4782-8edb-fc50b92940d7','449d110c-a311-43fe-8d20-0e23a68c5eb6','concept.gaussian.guided',0,'Разбор · Вычислите логарифм плотности в центре гауссова распределения.','Вычислите логарифм плотности в центре гауссова распределения. Реализуйте solve(values) для любого допустимого входа. values=[x,mu,sigma], sigma∈[1e−3,100]. Выход [logDensity]. Все числа конечны, |value|≤1000. Не меняйте input. Невалидные данные: ValueError/RangeError/InputError (Rust Result). Допуск atol=1e−12,rtol=1e−10. Область subskill: Логарифм плотности одномерного гауссова распределения. Плотность не равна вероятности одной точки; генерация выборки и интегрирование по интервалу не реализованы.

log p(x)=−log(σ)−½log(2π)−(x−μ)²/(2σ²)');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('1684d793-4a1f-4a84-8263-377f21174006','449d110c-a311-43fe-8d20-0e23a68c5eb6','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def solve(values: list[float]) -> list[float]:
    raise NotImplementedError("Реализуйте формулу и контракт")
','solve','[{"input":{"values":[0,0,1]},"output":[-0.9189385332046727]},{"input":{"values":[3,2,1]},"output":[-1.4189385332046727]},{"input":{"values":[2,2,2]},"output":[-1.612085713764618]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('1684d793-4a1f-4a84-8263-377f21174006','ba9e9e01-6659-4782-8edb-fc50b92940d7','c786c798bc08849accc437f0f1b8b5907fdc1e91ef36d71d9f982c19e0243d74','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Нормировочный член −log sigma нужен даже в центре. Квадрат стандартизованного x не обрезайте.','Высота плотности не равна вероятности ровно одной точки.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 3 <= len(values) <= 3 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
    x,mu,sigma = values
    if not 1e-3 <= sigma <= 100:
        raise ValueError("sigma")
    return [-math.log(sigma)-.5*math.log(2*math.pi)-.5*((x-mu)/sigma)**2]
','x=mu,sigma=1 → −.5ln(2π); sigma=2 даёт дополнительно −ln2. Высота плотности не равна вероятности ровно одной точки. Границы: Логарифм плотности одномерного гауссова распределения. Плотность не равна вероятности одной точки; генерация выборки и интегрирование по интервалу не реализованы. Это открытая formative самопроверка; quiz/fixture не создают server pass.');
