','solve','[{"input":{"values":[0,0,1]},"output":[-0.9189385332046727]},{"input":{"values":[3,2,1]},"output":[-1.4189385332046727]},{"input":{"values":[2,2,2]},"output":[-1.612085713764618]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('f330ceae-68a2-49c4-8aa4-a448b9d088fe','ba9e9e01-6659-4782-8edb-fc50b92940d7','b561718870b635e6334053bfaa01cbc58fbbd80f7655659db92d521a8de3b627','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"javascript","entrypoint":"solve"}'::jsonb,array['Нормировочный член −log sigma нужен даже в центре. Квадрат стандартизованного x не обрезайте.','Высота плотности не равна вероятности ровно одной точки.']::text[],'function solve(values) {
  if(!Array.isArray(values)||values.length<3||values.length>3||values.some(x=>typeof x!=="number"||!Number.isFinite(x)||Math.abs(x)>1000))throw new RangeError("Форма и конечные числа ±1000");
  const [x,mu,sigma]=values;if(sigma<1e-3||sigma>100)throw new RangeError("sigma");
