pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()<4 || values.len()>4 || values.iter().any(|x|!x.is_finite()||x.abs()>1000.0){return Err(InputError);}
    let (mq,sq,mp,sp)=(values[0],values[1],values[2],values[3]);if !(1e-3..=100.0).contains(&sq)||!(1e-3..=100.0).contains(&sp){return Err(InputError);}
    Ok(vec![(sp/sq).ln()+(sq*sq+(mq-mp).powi(2))/(2.0*sp*sp)-0.5])
}
