  if(!Array.isArray(values)||values.length<2||values.length>34||values.some(x=>typeof x!=="number"||!Number.isFinite(x)||Math.abs(x)>1000))throw new RangeError("Форма и конечные числа ±1000");
  const [mu,sigma]=values;if(sigma<1e-3||sigma>100)throw new RangeError("sigma");
  return [values.slice(2).reduce((s,x)=>s-Math.log(sigma)-.5*Math.log(2*Math.PI)-.5*((x-mu)/sigma)**2,0)];
}
