insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('8db1139b-4c87-496a-8122-c1f19a9c81af','ba9e9e01-6659-4782-8edb-fc50b92940d7','b696da827f439ccf85e9208cc81b829970190d2a09baf2e0655ec84dea0c1338','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"solve"}'::jsonb,array['Для независимых данных логарифм правдоподобия складывается. Не делите на число наблюдений: здесь нужна сумма, а не среднее.','Логарифм правдоподобия независимых наблюдений складывается.']::text[],'#[derive(Debug,PartialEq)]
pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()<2 || values.len()>34 || values.iter().any(|x|!x.is_finite()||x.abs()>1000.0){return Err(InputError);}
    let (m,s)=(values[0],values[1]);if !(1e-3..=100.0).contains(&s){return Err(InputError);}
    Ok(vec![values[2..].iter().map(|x|-s.ln()-0.5*(2.0*std::f64::consts::PI).ln()-0.5*((x-m)/s).powi(2)).sum()])
}
','mu=0,sigma=1,xs=[−1,1] → −ln(2π)−1. Удвоение набора данных удваивает сумму логарифмов правдоподобия. Логарифм правдоподобия независимых наблюдений складывается. Границы: Правдоподобие фиксированных наблюдений; это не нормированное апостериорное распределение параметров. Это открытая formative самопроверка; quiz/fixture не создают server pass.');
