insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('60635a95-1f46-48ec-8a37-7cce5530d3c6','ba9e9e01-6659-4782-8edb-fc50b92940d7','4158086c2fc1b3c6379b7618af70e96fdc6099f48670cc726c8ffe39a4f1e9af','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Для независимых данных логарифм правдоподобия складывается. Не делите на число наблюдений: здесь нужна сумма, а не среднее.','Дублирование набора данных удваивает сумму логарифмов правдоподобия.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 2 <= len(values) <= 34 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
    mu,sigma = values[:2]
    if not 1e-3 <= sigma <= 100:
        raise ValueError("sigma")
    return [sum(-math.log(sigma)-.5*math.log(2*math.pi)-.5*((x-mu)/sigma)**2 for x in values[2:])]
','mu=0,sigma=1,xs=[−1,1] → −ln(2π)−1. Удвоение набора данных удваивает сумму логарифмов правдоподобия. Дублирование набора данных удваивает сумму логарифмов правдоподобия. Границы: Правдоподобие фиксированных наблюдений; это не нормированное апостериорное распределение параметров. Это открытая formative самопроверка; quiz/fixture не создают server pass.');
