pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()<2 || values.len()>34 || values.iter().any(|x|!x.is_finite()||x.abs()>1000.0){return Err(InputError);}
    let (m,s)=(values[0],values[1]);if !(1e-3..=100.0).contains(&s){return Err(InputError);}
    Ok(vec![values[2..].iter().map(|x|-s.ln()-0.5*(2.0*std::f64::consts::PI).ln()-0.5*((x-m)/s).powi(2)).sum()])
}
