','solve','[{"input":{"values":[0.25,1,0.5]},"output":[0.4,0.6,0.625]},{"input":{"values":[0.25,0.5,0.5]},"output":[0.25,0.75,0.5]},{"input":{"values":[0.25,0,1]},"output":[0,1,0.75]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('ae519126-f9f0-4c49-8a37-37fd8f36c3d8','ba9e9e01-6659-4782-8edb-fc50b92940d7','18c1004c8b0f485185f69fe52e4a9868d1ec704d2a60a03c55342508fd70cebf','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Правдоподобие не нужно нормировать по гипотезам. Нормируется произведение априорной вероятности и правдоподобия.','Апостериорное распределение нормирует априорную вероятность × правдоподобие, а не правдоподобие отдельно.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 3 <= len(values) <= 3 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
    p,l0,l1 = values
    if any(not 0 <= x <= 1 for x in values):
        raise ValueError("probabilities")
    e = p*l0+(1-p)*l1
    if e < 1e-12:
        raise ValueError("zero evidence")
    q = p*l0/e
    return [q,1-q,e]
