insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('1eca43b0-1dd4-4609-85b0-c6a71f5afbbb','8f2368c8-2057-4aa2-88f6-7f8266fa5507','ba9e9e01-6659-4782-8edb-fc50b92940d7','1eca43b0-1dd4-4609-85b0-c6a71f5afbbb','concept.monte-carlo.guided',0,'Разбор · Рассчитайте среднее и оценку неопределённости двух наблюдений.','Рассчитайте среднее и оценку неопределённости двух наблюдений. Реализуйте solve(values) для любого допустимого входа. values — 1–32 готовых значений f(samples). Выход [mean,sampleVariance,standardError,uncertaintyAvailable]. При n=1 выходные дисперсия/SE=0 как условные значения, flag=0; при n≥2 flag=1. SE интерпретируется только при независимых наблюдениях. Все числа конечны, |value|≤1000. Не меняйте input. Невалидные данные: ValueError/RangeError/InputError (Rust Result). Допуск atol=1e−12,rtol=1e−10. Область subskill: Детерминированная сводка переданного набора; тестовые примеры не являются случайной выборкой Монте-Карло и не проверяют сходимость.

mean=Σv/n; sampleVariance=Σ(v−mean)²/(n−1); standardError=√(sampleVariance/n)');
insert into public.practice_variants(id,exercise_id,release_id,language,starter_code,entrypoint,public_tests,runtime_digest) values ('c5fea9d5-5db5-4e93-87b5-c0af381fb98c','1eca43b0-1dd4-4609-85b0-c6a71f5afbbb','ba9e9e01-6659-4782-8edb-fc50b92940d7','python','import math

def solve(values: list[float]) -> list[float]:
    raise NotImplementedError("Реализуйте формулу и контракт")
','solve','[{"input":{"values":[1,3]},"output":[2,2,1,1]},{"input":{"values":[1,1,3,3]},"output":[2,1.3333333333333333,0.5773502691896257,1]},{"input":{"values":[5]},"output":[5,0,0,0]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('c5fea9d5-5db5-4e93-87b5-c0af381fb98c','ba9e9e01-6659-4782-8edb-fc50b92940d7','40302bb9c1d7b1b98599079539282cfd55ff99bfa200766ac43bd224ee7fd2ae','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Для несмещённой выборочной дисперсии делитель n−1. Условное значение 0 при одном наблюдении не означает доказанное отсутствие неопределённости.','Выборочная дисперсия имеет знаменатель n−1.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 1 <= len(values) <= 32 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
    n = len(values)
    m = sum(values)/n
    if n == 1:
        return [m,0,0,0]
    v = sum((x-m)**2 for x in values)/(n-1)
    return [m,v,math.sqrt(v/n),1]
