def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 1 <= len(values) <= 32 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
    n = len(values)
    m = sum(values)/n
    if n == 1:
        return [m,0,0,0]
    v = sum((x-m)**2 for x in values)/(n-1)
    return [m,v,math.sqrt(v/n),1]
