insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('a847ebcd-af73-4d4e-8600-428444e4e171','ba9e9e01-6659-4782-8edb-fc50b92940d7','819954a8386e31ad895e97ccea14c792af65a40a0c3c99eb87ea3d9683161555','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"rust","entrypoint":"solve"}'::jsonb,array['Для несмещённой выборочной дисперсии делитель n−1. Условное значение 0 при одном наблюдении не означает доказанное отсутствие неопределённости.','Одно наблюдение не позволяет оценить дисперсию; условный ноль сопровождается флагом недоступности оценки.']::text[],'#[derive(Debug,PartialEq)]
pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()<1 || values.len()>32 || values.iter().any(|x|!x.is_finite()||x.abs()>1000.0){return Err(InputError);}
    let n=values.len();let m=values.iter().sum::<f64>()/n as f64;if n==1{return Ok(vec![m,0.0,0.0,0.0]);}
    let v=values.iter().map(|x|(x-m).powi(2)).sum::<f64>()/(n-1) as f64;Ok(vec![m,v,(v/n as f64).sqrt(),1.0])
}
','[1,3] → mean=2,variance=2,SE=1,flag=1. [5] → [5,0,0,0]. Одно наблюдение не позволяет оценить дисперсию; условный ноль сопровождается флагом недоступности оценки. Границы: Детерминированная сводка переданного набора; тестовые примеры не являются случайной выборкой Монте-Карло и не проверяют сходимость. Это открытая formative самопроверка; quiz/fixture не создают server pass.');
