insert into public.practice_exercises(id,topic_id,release_id,requirement_id,exercise_key,position,objective,prompt_markdown) values ('018fc179-29e2-4098-81d6-0bcc34f0120b','49b85b8d-3ce8-4b19-8565-bea5556ea5bc','ba9e9e01-6659-4782-8edb-fc50b92940d7','018fc179-29e2-4098-81d6-0bcc34f0120b','concept.noise-schedule.guided',0,'Разбор · Накопите долю сигнала двух последовательных шагов.','Накопите долю сигнала двух последовательных шагов. Реализуйте solve(values) для любого допустимого входа. values — 1–32 beta в (0,1). Выход — список всех накопленных alphaBar; каждый beta конечен. Индексы расписания — шаги времени, а не физические координаты. Все числа конечны, |value|≤1000. Не меняйте input. Невалидные данные: ValueError/RangeError/InputError (Rust Result). Допуск atol=1e−12,rtol=1e−10. Область subskill: Накопленное произведение прямого расписания; обратная модель не реализована, полное стирание сигнала за конечное число шагов не гарантируется.

alphaBar[t]=∏s≤t(1−beta[s]); signalCoefficient=√alphaBar; noiseCoefficient=√(1−alphaBar)');
