','solve','[{"input":{"values":[0.2,0.5]},"output":[0.8,0.4]},{"input":{"values":[0.1,0.2,0.3]},"output":[0.9,0.72,0.504]},{"input":{"values":[0.5,0.5,0.5]},"output":[0.5,0.25,0.125]}]'::jsonb,null);
insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('0fd65ada-40f2-4219-826d-12fbe85fecdf','ba9e9e01-6659-4782-8edb-fc50b92940d7','b14de14533e2609b2e94c36eb3369d079372c4e4f6bbd78590fdfadb91039d17','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['Каждое накопленное произведение использует прежнее произведение, а не только текущий 1−beta.','alphaBar — произведение, а не сумма beta.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 1 <= len(values) <= 32 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
    if any(not 0 < b < 1 for b in values):
        raise ValueError("beta")
    p = 1
    out = []
    for b in values:
        p *= 1-b
        out.append(p)
    return out
','betas=[.2,.5] → alphaBar=[.8,.4]; квадраты коэффициентов сигнала/шума .4+.6=1. alphaBar — произведение, а не сумма beta. Границы: Накопленное произведение прямого расписания; обратная модель не реализована, полное стирание сигнала за конечное число шагов не гарантируется. Это открытая formative самопроверка; quiz/fixture не создают server pass.');
