pub struct InputError;
pub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {
    if values.len()<3 || values.len()>3 || values.iter().any(|x|!x.is_finite()||x.abs()>1000.0){return Err(InputError);}
    let (x,m,s)=(values[0],values[1],values[2]);if !(1e-3..=100.0).contains(&s){return Err(InputError);}
    Ok(vec![-(x-m)/(s*s)])
}
