    if not isinstance(values,list) or not 9 <= len(values) <= 9 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
