def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 1 <= len(values) <= 33 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
