insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('adb6a197-9e37-415a-82ca-6181a062c00e','ba9e9e01-6659-4782-8edb-fc50b92940d7','51833902b0aa11260f6d76de9a67c1f0c70aee6c8054a4abc5234eb49da43f99','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['E[score·baseline]=0 при общем базовом уровне для обоих действий. Взвесьте score0=1−p,score1=−p вероятностями.','Градиент J повышает вероятность действия с большей наградой.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 4 <= len(values) <= 4 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
    theta,r0,r1,b = values
    p = 1/(1+math.exp(-theta)) if theta >= 0 else math.exp(theta)/(1+math.exp(theta))
    g = p*(1-p)*(r0-r1)
    gb = p*(1-p)*(r0-b)+(1-p)*(-p)*(r1-b)
    return [p,p*r0+(1-p)*r1,g,gb]
