insert into private.practice_bundles(variant_id,release_id,bundle_sha256,grading_tests,expected_tests,runner_spec,hints,reference_solution,explanation) values ('861d7876-bcad-46f7-821c-1f68ae4d7ca9','ba9e9e01-6659-4782-8edb-fc50b92940d7','31e7106f50f7f234dd54c3ec79ae9547b79f5ebe3ee2d4ab9a42e7c130a0168e','[]',0,'{"enabled":false,"reason":"isolated_runner_not_verified","artifact_kind":"authored_help_only","language":"python","entrypoint":"solve"}'::jsonb,array['E[score·baseline]=0 при общем базовом уровне для обоих действий. Взвесьте score0=1−p,score1=−p вероятностями.','Базовый уровень, независимый от действия, не меняет ожидаемый градиент.']::text[],'import math

def solve(values: list[float]) -> list[float]:
    if not isinstance(values,list) or not 4 <= len(values) <= 4 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):
        raise ValueError("Форма и конечные числа ±1000")
    theta,r0,r1,b = values
    p = 1/(1+math.exp(-theta)) if theta >= 0 else math.exp(theta)/(1+math.exp(theta))
    g = p*(1-p)*(r0-r1)
    gb = p*(1-p)*(r0-b)+(1-p)*(-p)*(r1-b)
    return [p,p*r0+(1-p)*r1,g,gb]
